            let filter = build_filter(sub_m);
            let no_grouping = sub_m.is_present("no_grouping");
            let number = sub_m.value_of("NUMBER").and_then(|n| n.parse().ok());
            let round = sub_m.value_of("round").and_then(parse_round);
            let project = sub_m.value_of("PROJECT");
            controller::list(&file, filter, no_grouping, number, round, project);
        }
        ("projects", Some(sub_m)) => {
            let file = get_file_path(file_path);
            let current_only = sub_m.is_present("current");
            let no_quotes = sub_m.is_present("no_quotes");
            controller::projects(&file, current_only, no_quotes);
        }
        ("report", Some(sub_m)) => {
            let file = get_file_path(file_path);
            let filter = build_filter(sub_m);
            let round = sub_m.value_of("round").and_then(parse_round);
            let project = sub_m.value_of("PROJECT");
            controller::report(&file, filter, round, project);
        }
        ("sanity", Some(_sub_m)) => {
            let file = get_file_path(file_path);
            controller::sanity(&file);
        }
        ("search", Some(sub_m)) => {
            let file = get_file_path(file_path);
            let term = sub_m.value_of("SEARCH_TERM").unwrap_or("");
            controller::search(&file, term);
        }
        ("start", Some(sub_m)) => {
            let file = get_file_path(file_path);
            let description = sub_m.value_of("DESCRIPTION").unwrap();
            let project = sub_m.value_of("PROJECT").unwrap();
            let time = parse_time_option(sub_m.value_of("TIME"));
            controller::start(&file, description, project, time);
        }
        ("status", Some(sub_m)) => {
            let file = get_file_path(file_path);
            let project = sub_m.value_of("PROJECT");
            controller::status(&file, project);
        }
        ("stop", Some(sub_m)) => {
            let file = get_file_path(file_path);
            let time = parse_time_option(sub_m.value_of("TIME"));
            controller::stop(&file, time);
        }
        _ => {}
