}

fn get_file_path(file_path: Option<&str>) -> String {
    match file_path {
        Some(p) => p.to_string(),
        None => {
            eprintln!("Error: Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable");
            std::process::exit(1);
        }
    }
}

fn parse_time_option(time_str: Option<&str>) -> Option<NaiveTime> {
    time_str.and_then(|t| NaiveTime::parse_from_str(t, "%H:%M").ok())
}

fn parse_round(round_str: &str) -> Option<i64> {
    if round_str.ends_with('m') {
        round_str[..round_str.len()-1].parse::<i64>().ok()
    } else if round_str.ends_with('h') {
        round_str[..round_str.len()-1].parse::<i64>().ok().map(|h| h * 60)
    } else {
        None
    }
}

pub struct DateFilter {
    pub from: Option<NaiveDate>,
    pub to: Option<NaiveDate>,
}

fn build_filter(sub_m: &clap::ArgMatches) -> DateFilter {
    let today = Local::now().date_naive();

    if sub_m.is_present("today") {
        return DateFilter { from: Some(today), to: Some(today) };
    }

    if sub_m.is_present("yesterday") {
        let yesterday = today - Duration::days(1);
        return DateFilter { from: Some(yesterday), to: Some(yesterday) };
    }

    if sub_m.is_present("current_week") {
        // Monday to Sunday
        let weekday = today.weekday().num_days_from_monday();
        let monday = today - Duration::days(weekday as i64);
        let sunday = monday + Duration::days(6);
        return DateFilter { from: Some(monday), to: Some(sunday) };
    }

    if sub_m.is_present("last_week") {
        let weekday = today.weekday().num_days_from_monday();
        let this_monday = today - Duration::days(weekday as i64);
        let last_monday = this_monday - Duration::days(7);
        let last_sunday = last_monday + Duration::days(6);
        return DateFilter { from: Some(last_monday), to: Some(last_sunday) };
    }

    if let Some(date_str) = sub_m.value_of("DATE") {
        if let Ok(date) = NaiveDate::parse_from_str(date_str, "%Y-%m-%d") {
            return DateFilter { from: Some(date), to: Some(date) };
        }
    }

    let from = sub_m.value_of("FROM_DATE").and_then(|d| NaiveDate::parse_from_str(d, "%Y-%m-%d").ok());
    let to = sub_m.value_of("TO_DATE").and_then(|d| NaiveDate::parse_from_str(d, "%Y-%m-%d").ok());

    DateFilter { from, to }
}
