        return "<1m".to_string();
    }
    let hours = minutes / 60;
    let mins = minutes % 60;
    if hours == 0 {
        format!("{}m", mins)
    } else if mins == 0 {
        format!("{}h 00m", hours)
    } else {
        format!("{}h {:02}m", hours, mins)
    }
}

pub fn parse_activity(line: &str, line_number: usize) -> Result<Activity, String> {
    let line = line.trim();
    if line.is_empty() {
        return Err("empty line".to_string());
    }

    // Try to parse: "DATETIME - DATETIME | PROJECT | DESCRIPTION"
    // or: "DATETIME | PROJECT | DESCRIPTION"

    // Find the project/description separator
    // The format uses " | " as separator
    let parts: Vec<&str> = line.splitn(3, " | ").collect();
    if parts.len() != 3 {
        return Err(format!("could not parse activity (Line: {})", line_number));
    }

    let time_part = parts[0].trim();
    let project = parts[1].trim().to_string();
    let description = parts[2].trim().to_string();

    // Parse time_part: either "DATETIME - DATETIME" or "DATETIME"
    let (start, end) = if time_part.contains(" - ") {
        let time_parts: Vec<&str> = time_part.splitn(2, " - ").collect();
        if time_parts.len() != 2 {
            return Err(format!("could not parse activity (Line: {})", line_number));
        }
        let start = parse_datetime(time_parts[0].trim())
            .ok_or_else(|| format!("could not parse activity (Line: {})", line_number))?;
        let end = parse_datetime(time_parts[1].trim())
            .ok_or_else(|| format!("could not parse activity (Line: {})", line_number))?;
        (start, Some(end))
    } else {
        let start = parse_datetime(time_part)
            .ok_or_else(|| format!("could not parse activity (Line: {})", line_number))?;
        (start, None)
    };

    Ok(Activity {
        start,
        end,
        project,
        description,
        line_number: Some(line_number),
    })
}

fn parse_datetime(s: &str) -> Option<NaiveDateTime> {
    NaiveDateTime::parse_from_str(s, "%Y-%m-%d %H:%M").ok()
}

pub fn round_datetime(dt: NaiveDateTime, round_minutes: i64) -> NaiveDateTime {
    let minutes = dt.timestamp() / 60;
    let rounded = ((minutes + round_minutes / 2) / round_minutes) * round_minutes;
    NaiveDateTime::from_timestamp_opt(rounded * 60, 0).unwrap_or(dt)
}
