            let mut project_set = std::collections::BTreeSet::new();
            for activity in &data.activities {
                if current_only {
                    if activity.is_running() {
                        project_set.insert(activity.project.clone());
                    }
                } else {
                    project_set.insert(activity.project.clone());
                }
            }
