    duration.num_minutes().max(0)
}

fn print_report(activities: &[Activity], now: NaiveDateTime) {
    // Group by project, then by description, sum durations
    let mut project_map: BTreeMap<String, BTreeMap<String, i64>> = BTreeMap::new();

    for activity in activities {
        let minutes = activity_duration_minutes(activity, now);
        project_map
            .entry(activity.project.clone())
            .or_default()
            .entry(activity.description.clone())
            .and_modify(|v| *v += minutes)
            .or_insert(minutes);
    }

    // Calculate total
    let total_minutes: i64 = project_map.values()
        .flat_map(|tasks| tasks.values())
        .sum();

    // Find max name width across all projects and tasks
    let max_label_width = project_map.iter()
        .flat_map(|(proj, tasks)| {
            let mut widths = vec![proj.len()];
            widths.extend(tasks.keys().map(|t| t.len() + 4)); // 4 for indentation
            widths
        })
        .chain(std::iter::once("Total".len()))
        .max()
        .unwrap_or(5);

    // Also check "Total" width
    let max_label_width = max_label_width.max("Total".len());

    // The duration format width - find max duration string
    let max_duration_width: usize = {
        let mut durations: Vec<i64> = project_map.values()
            .flat_map(|tasks| tasks.values())
            .cloned()
            .collect();
        let project_totals: Vec<i64> = project_map.values()
            .map(|tasks| tasks.values().sum())
            .collect();
        durations.extend(project_totals);
        durations.push(total_minutes);
        durations.iter()
            .map(|&m| format_duration(m).len())
            .max()
            .unwrap_or(3)
    };

    for (project, tasks) in &project_map {
        let project_total: i64 = tasks.values().sum();
        let project_dur = format_duration(project_total);

        // Dots for project line
        let dots_needed = max_label_width - project.len() + 1;
        let dots = ".".repeat(dots_needed);
        println!("\x1b[1m{}{} {:>dwidth$}\x1b[0m",
            project, dots, project_dur,
            dwidth = max_duration_width
        );

        for (task, &minutes) in tasks {
            let task_dur = format_duration(minutes);
            let task_label = format!("    {}", task);
            let dots_needed = max_label_width - task_label.len() + 1;
            let dots = ".".repeat(dots_needed);
            println!("{}{} {:>dwidth$}",
                task_label, dots, task_dur,
                dwidth = max_duration_width
            );
        }
        println!();
    }

    // Total line
    let total_dur = format_duration(total_minutes);
    let dots_needed = max_label_width - "Total".len() + 1;
    let dots = ".".repeat(dots_needed);
    println!("\x1b[1m{}{} {:>dwidth$}\x1b[0m",
        "Total", dots, total_dur,
        dwidth = max_duration_width
    );
}

fn calc_duration_in_range(activities: &[&Activity], from: NaiveDateTime, to: NaiveDateTime, now: NaiveDateTime) -> i64 {
    let mut total = 0i64;
    for activity in activities {
        let start = activity.start;
        let end = activity.end.unwrap_or(now);

        // Activity must overlap with [from, to)
        if end <= from || start >= to {
            continue;
        }

        let effective_start = start.max(from);
        let effective_end = end.min(to);

        if effective_end > effective_start {
            total += (effective_end - effective_start).num_minutes();
        }
    }
    total
}

fn calc_duration_in_range_from(activities: &[&Activity], from: NaiveDateTime, now: NaiveDateTime) -> i64 {
    let mut total = 0i64;
    for activity in activities {
        let start = activity.start;
        let end = activity.end.unwrap_or(now);

        if end <= from {
            continue;
        }

        let effective_start = start.max(from);

        if end > effective_start {
            total += (end - effective_start).num_minutes();
        }
    }
    total
}

