            // Stop all currently running activities
            for activity in data.activities.iter_mut() {
                if activity.is_running() {
                    activity.end = Some(now);
                    print_stopped(activity);
                }
            }

            // Get unique activities and find the one to continue
            let unique = get_unique_recent_activities(&data.activities, usize::MAX);

            if let Some((_, activity)) = unique.iter().find(|(idx, _)| *idx == number) {
                let mut desc = activity.description.clone();
