pub fn list(file_path: &str, filter: DateFilter, no_grouping: bool, number: Option<usize>, round_minutes: Option<i64>, project: Option<&str>) {
    match read_activities(file_path) {
        Ok(data) => {
            let now = now_datetime();
            let mut activities: Vec<Activity> = data.activities.clone();

            // Apply project filter
            if let Some(proj) = project {
                activities.retain(|a| a.project == proj);
            }

            // Apply date filter
            apply_date_filter(&mut activities, &filter);

            // Apply number limit (take last n)
            if let Some(n) = number {
                if activities.len() > n {
                    let skip = activities.len() - n;
                    activities = activities.into_iter().skip(skip).collect();
                }
            }

            // Apply rounding
            if let Some(round) = round_minutes {
                for a in activities.iter_mut() {
                    a.start = round_datetime(a.start, round);
                    if let Some(end) = a.end {
                        a.end = Some(round_datetime(end, round));
                    }
                }
            }

            println!();
            if no_grouping {
                print_list_no_grouping(&activities, now);
            } else {
                print_list_grouped(&activities, now, &filter);
            }
            println!();
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}

