pub fn status(file_path: &str, project: Option<&str>) {
    match read_activities(file_path) {
        Ok(data) => {
            let now = now_datetime();
            let today = now.date();
            let activities: Vec<Activity> = data.activities.clone();

            // Find currently running activities
            let running: Vec<&Activity> = activities.iter()
                .filter(|a| a.is_running())
                .filter(|a| project.map_or(true, |p| a.project == p))
                .collect();

            // Calculate durations for today, current week, current month
            let today_start = NaiveDateTime::new(today, NaiveTime::from_hms_opt(0, 0, 0).unwrap());
            let tomorrow_start = NaiveDateTime::new(today + Duration::days(1), NaiveTime::from_hms_opt(0, 0, 0).unwrap());

            let weekday = today.weekday().num_days_from_monday();
            let monday = today - Duration::days(weekday as i64);
            let week_start = NaiveDateTime::new(monday, NaiveTime::from_hms_opt(0, 0, 0).unwrap());

            let month_start = NaiveDateTime::new(
                NaiveDate::from_ymd_opt(today.year(), today.month(), 1).unwrap(),
                NaiveTime::from_hms_opt(0, 0, 0).unwrap()
            );

            let filtered: Vec<&Activity> = activities.iter()
                .filter(|a| project.map_or(true, |p| a.project == p))
                .collect();

            let today_minutes = calc_duration_in_range(&filtered, today_start, tomorrow_start, now);
            let week_minutes = calc_duration_in_range(&filtered, week_start, NaiveDateTime::new(monday + Duration::days(7), NaiveTime::from_hms_opt(0, 0, 0).unwrap()), now);
            let month_minutes = calc_duration_in_range_from(&filtered, month_start, now);

            // Print status
            print_status(project, &running, today_minutes, week_minutes, month_minutes, now);
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}

