pub fn check(file_path: &str) {
    let content = match std::fs::read_to_string(file_path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Error: Could not read from file: {}\n\nCaused by:\n    {}", file_path, e);
            std::process::exit(1);
        }
    };

    let mut errors = Vec::new();
    for (i, line) in content.lines().enumerate() {
        let line_num = i + 1;
        if line.trim().is_empty() {
            continue;
        }
        if let Err(e) = crate::activity::parse_activity(line, line_num) {
            errors.push((line_num, line.to_string(), e));
        }
    }

    if errors.is_empty() {
        println!("All lines in the file have been successfully parsed as activities.");
    } else {
        println!("Found {} line(s) with parsing errors", errors.len());
        println!();
        for (_, line, err) in &errors {
            println!("{}", line);
            println!("  -> {}", err);
        }
    }
}

pub fn sanity(file_path: &str) {
    match read_activities(file_path) {
        Ok(data) => {
            let mut found_issues = false;
            let activities = &data.activities;

            for i in 1..activities.len() {
                let prev = &activities[i-1];
                let curr = &activities[i];

                // Check if current activity started before previous ended
                if let Some(prev_end) = prev.end {
                    if curr.start < prev_end {
                        if !found_issues {
                            // Don't print header - just print each issue
                        }
                        let end_str = curr.end.map(|e| e.format("%Y-%m-%d %H:%M").to_string())
                            .unwrap_or_default();
                        let line_num = curr.line_number.unwrap_or(i + 1);
                        println!("Activity started before another activity ended");
                        println!("{} (Started: {}, Ended: {}, Line: {})",
                            curr.description,
                            curr.start.format("%Y-%m-%d %H:%M"),
                            curr.end.map(|e| e.format("%Y-%m-%d %H:%M").to_string()).unwrap_or_default(),
                            line_num
                        );
                        println!();
                        found_issues = true;
                    }
                }
            }

            if !found_issues {
                println!("No unusual activities.");
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}

pub fn continue_activity(file_path: &str, number: usize, description: Option<&str>, project: Option<&str>, time: Option<NaiveTime>) {
    let now = with_time_override(time);

    match read_activities(file_path) {
        Ok(mut data) => {
            // Stop all currently running activities
            for activity in data.activities.iter_mut() {
                if activity.is_running() {
                    activity.end = Some(now);
                    print_stopped(activity);
                }
            }

            // Get unique activities and find the one to continue
            let unique = get_unique_recent_activities(&data.activities, usize::MAX);

            if let Some((_, activity)) = unique.iter().find(|(idx, _)| *idx == number) {
                let mut desc = activity.description.clone();
                let mut proj = activity.project.clone();

                if let Some(d) = description {
                    desc = d.to_string();
                }
                if let Some(p) = project {
                    proj = p.to_string();
                }

                let new_activity = Activity::new(proj, desc, now);
                data.activities.push(new_activity.clone());

                if let Err(e) = write_activities(file_path, &data.activities) {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                }
                print_started(&new_activity);
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}

