fn apply_date_filter(activities: &mut Vec<Activity>, filter: &DateFilter) {
    if filter.from.is_none() && filter.to.is_none() {
        return;
    }
    activities.retain(|a| {
        let date = a.start.date();
        let from_ok = filter.from.map_or(true, |f| date >= f);
        let to_ok = filter.to.map_or(true, |t| date <= t);
        from_ok && to_ok
    });
}

fn get_unique_recent_activities(activities: &[Activity], max: usize) -> Vec<(usize, &Activity)> {
    // Get unique activities by (project, description), preserving order from end
    // Index is assigned in reverse order (0 = most recent)
    let mut seen = std::collections::HashSet::new();
    let mut unique: Vec<&Activity> = Vec::new();

    for activity in activities.iter().rev() {
        let key = (activity.project.clone(), activity.description.clone());
        if !seen.contains(&key) {
            seen.insert(key);
            unique.push(activity);
            if unique.len() >= max {
                break;
            }
        }
    }

    unique.iter().enumerate().map(|(i, a)| (i, *a)).collect()
}

