    if activities.is_empty() {
        // Print header anyway
        let desc_width = 11usize;
        let proj_width = 7usize;
        print_list_header_grouped(desc_width, proj_width);
        println!();
        return;
    }

    // Calculate column widths
    let desc_width = activities.iter()
        .map(|a| a.description.len())
        .max()
        .unwrap_or(11)
        .max(11);

    let proj_width = activities.iter()
        .map(|a| a.project.len())
        .max()
        .unwrap_or(7)
        .max(7);

    // Check if any activities span multiple days (to determine if stopped column needs date)
    let has_multiday = activities.iter().any(|a| is_multi_day(a));

    print_list_header_grouped(desc_width, proj_width);
    println!();

    // Group by date
    let mut date_groups: BTreeMap<NaiveDate, Vec<&Activity>> = BTreeMap::new();
    for activity in activities {
        let date = activity.start.date();
        date_groups.entry(date).or_default().push(activity);
    }

    for (date, day_activities) in &date_groups {
        // Calculate total duration for day
        let total_minutes: i64 = day_activities.iter()
            .map(|a| activity_duration_minutes(a, now))
            .sum();

        println!("\x1b[1m{}\t{}\x1b[0m", date.format("%Y-%m-%d"), format_duration(total_minutes));

        for activity in day_activities {
            let duration = format_duration(activity_duration_minutes(activity, now));
            let start_str = activity.start.format("%H:%M").to_string();

            let (stopped_str, end_needs_date) = match activity.end {
                Some(end) => {
                    if end.date() != activity.start.date() {
                        (end.format("%Y-%m-%d %H:%M").to_string(), true)
                    } else {
                        (end.format("%H:%M").to_string(), false)
                    }
                }
                None => ("-".to_string(), false),
            };

            let color = if activity.is_running() {
                "\x1b[32m" // green
            } else if is_multi_day(activity) {
                "\x1b[33m" // yellow  
            } else {
                ""
            };
            let reset = if !color.is_empty() { "\x1b[0m" } else { "" };

            // Determine stopped column width - if any multiday, use wider format
            let stopped_display = if has_multiday && !activity.is_running() {
                // Need to check if the stopped has a date component
                if end_needs_date {
                    format!("{:<15}", stopped_str)
                } else {
                    format!("{:<15}", stopped_str)
                }
            } else {
                format!("{:<7}", stopped_str)
            };

            print!("{}{:<7} {:<7} {:<dwidth$} {:<pwidth$} {:<8} {}",
