        "\x1b[4m{}\x1b[0m \x1b[4m{}\x1b[0m \x1b[4m{}\x1b[0m \x1b[4m{}\x1b[0m \x1b[4m{}\x1b[0m ",
        started_col, stopped_col, desc_col, proj_col, "Duration"
    );
    println!();

    // Group by date
    let mut date_groups: BTreeMap<NaiveDate, Vec<&Activity>> = BTreeMap::new();
    for activity in activities {
        date_groups.entry(activity.start.date()).or_default().push(activity);
    }

    for (date, day_activities) in &date_groups {
        let total_minutes: i64 = day_activities
            .iter()
            .map(|a| activity_duration_minutes(a, now))
            .sum();

        println!(
            "\x1b[1m{}\t{}\x1b[0m",
