                    } else {
                        end.format("%H:%M").to_string()
                    }
                }
                None => "-".to_string(),
            };
            let stopped_padded = pad_nbsp(&stopped_str, stopped_width);

            let desc_padded = pad_nbsp(&activity.description, desc_width);
            let proj_padded = pad_nbsp(&activity.project, proj_width);

            let running = activity.is_running();
            let multiday = is_multi_day(activity);

            if running {
                println!(
                    "\x1b[32m{}\x1b[0m \x1b[32m{}\x1b[0m \x1b[32m{}\x1b[0m \x1b[32m{}\x1b[0m \x1b[32m{}\x1b[0m ",
                    start_padded, stopped_padded, desc_padded, proj_padded, dur_padded
                );
            } else if multiday {
                println!(
                    "\x1b[33m{}\x1b[0m \x1b[33m{}\x1b[0m \x1b[33m{}\x1b[0m \x1b[33m{}\x1b[0m \x1b[33m{}\x1b[0m ",
                    start_padded, stopped_padded, desc_padded, proj_padded, dur_padded
