        .map(|(_, a)| a.project.chars().count())
        .max()
        .unwrap_or(7)
        .max(7); // "Project" = 7

    // Header: underlined " #" + NBSP*(idx_width-2) + " " + desc col + " " + proj col + " "
    let hash_col = pad_nbsp(" #", idx_width);
    let desc_col = pad_nbsp("Description", desc_width);
    let proj_col = pad_nbsp("Project", proj_width);
    println!(
        "\x1b[4m{}\x1b[0m \x1b[4m{}\x1b[0m \x1b[4m{}\x1b[0m ",
