fn print_started(activity: &Activity) {
    println!(
        "Started activity: \"{}\" ({}) at {}",
        activity.description,
        activity.project,
        activity.start.format("%Y-%m-%d %H:%M")
    );
}

fn print_stopped(activity: &Activity) {
    let duration = format_duration(activity.duration_minutes());
    println!(
        "Stopped activity: \"{}\" ({}) started at {} ({})",
        activity.description,
        activity.project,
        activity.start.format("%Y-%m-%d %H:%M"),
        duration
    );
}

fn print_canceled(activity: &Activity) {
