fn print_list_grouped(activities: &[Activity], now: NaiveDateTime) {
    // Determine column widths
    let desc_width = activities
        .iter()
        .map(|a| a.description.chars().count())
        .max()
        .unwrap_or(11)
        .max(11);
    let proj_width = activities
        .iter()
        .map(|a| a.project.chars().count())
        .max()
        .unwrap_or(7)
        .max(7);
    let dur_width = activities
        .iter()
        .map(|a| format_duration(activity_duration_minutes(a, now)).len())
        .max()
        .unwrap_or(8)
        .max(8);

    // Check if any multi-day activities
    let has_multiday = activities.iter().any(|a| is_multi_day(a));
    // Stopped column: 7 if no multiday, 16 if multiday
    let stopped_width = if has_multiday { 16 } else { 7 };

    // Print header
    // Started column = 7 (HH:MM + 2 NBSP)
    let started_col = pad_nbsp("Started", 7);
    let stopped_col = pad_nbsp("Stopped", stopped_width);
    let desc_col = pad_nbsp("Description", desc_width);
    let proj_col = pad_nbsp("Project", proj_width);
    println!(
        "\x1b[4m{}\x1b[0m \x1b[4m{}\x1b[0m \x1b[4m{}\x1b[0m \x1b[4m{}\x1b[0m \x1b[4m{}\x1b[0m ",
        started_col, stopped_col, desc_col, proj_col, "Duration"
    );
    println!();

    // Group by date
    let mut date_groups: BTreeMap<NaiveDate, Vec<&Activity>> = BTreeMap::new();
    for activity in activities {
        date_groups.entry(activity.start.date()).or_default().push(activity);
    }

    for (date, day_activities) in &date_groups {
        let total_minutes: i64 = day_activities
            .iter()
            .map(|a| activity_duration_minutes(a, now))
            .sum();

        println!(
            "\x1b[1m{}\t{}\x1b[0m",
            date.format("%Y-%m-%d"),
            format_duration(total_minutes)
        );

        for activity in day_activities {
            let duration = format_duration(activity_duration_minutes(activity, now));
            let dur_padded = pad_nbsp(&duration, dur_width);

            let start_str = activity.start.format("%H:%M").to_string();
            let start_padded = pad_nbsp(&start_str, 7);

            let stopped_str = match activity.end {
                Some(end) => {
                    if end.date() != activity.start.date() {
                        end.format("%Y-%m-%d %H:%M").to_string()
                    } else {
                        end.format("%H:%M").to_string()
                    }
                }
                None => "-".to_string(),
            };
            let stopped_padded = pad_nbsp(&stopped_str, stopped_width);

            let desc_padded = pad_nbsp(&activity.description, desc_width);
            let proj_padded = pad_nbsp(&activity.project, proj_width);

            let running = activity.is_running();
            let multiday = is_multi_day(activity);

            if running {
                println!(
                    "\x1b[32m{}\x1b[0m \x1b[32m{}\x1b[0m \x1b[32m{}\x1b[0m \x1b[32m{}\x1b[0m \x1b[32m{}\x1b[0m ",
                    start_padded, stopped_padded, desc_padded, proj_padded, dur_padded
                );
            } else if multiday {
                println!(
                    "\x1b[33m{}\x1b[0m \x1b[33m{}\x1b[0m \x1b[33m{}\x1b[0m \x1b[33m{}\x1b[0m \x1b[33m{}\x1b[0m ",
                    start_padded, stopped_padded, desc_padded, proj_padded, dur_padded
                );
            } else {
                println!(
                    "{} {} {} {} {} ",
                    start_padded, stopped_padded, desc_padded, proj_padded, dur_padded
                );
            }
        }
        println!();
    }
}

