        Ok(data) => {
            let now = now_datetime();
            let mut activities: Vec<Activity> = data.activities.clone();

            if let Some(proj) = project {
                activities.retain(|a| a.project == proj);
            }

            apply_date_filter(&mut activities, &filter);

            if let Some(round) = round_minutes {
                for a in activities.iter_mut() {
                    a.start = round_datetime(a.start, round);
                    if let Some(end) = a.end {
                        a.end = Some(round_datetime(end, round));
                    }
                }
            }

            println!();
            print_report(&activities, now);
            println!();
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}

pub fn status(file_path: &str, project: Option<&str>) {
    match read_activities(file_path) {
        Ok(data) => {
            let now = now_datetime();
            let today = now.date();

            let filtered: Vec<&Activity> = data
                .activities
                .iter()
                .filter(|a| project.map_or(true, |p| a.project == p))
                .collect();

            let running: Vec<&Activity> =
                filtered.iter().filter(|a| a.is_running()).copied().collect();

            let today_start = NaiveDateTime::new(today, NaiveTime::from_hms_opt(0, 0, 0).unwrap());
            let tomorrow_start = today_start + Duration::days(1);

            let weekday = today.weekday().num_days_from_monday();
            let monday = today - Duration::days(weekday as i64);
            let week_start = NaiveDateTime::new(monday, NaiveTime::from_hms_opt(0, 0, 0).unwrap());
            let next_week_start = week_start + Duration::days(7);

            let month_start = NaiveDateTime::new(
                NaiveDate::from_ymd_opt(today.year(), today.month(), 1).unwrap(),
                NaiveTime::from_hms_opt(0, 0, 0).unwrap(),
            );

            let today_minutes =
                calc_duration_in_range(&filtered, today_start, tomorrow_start, now);
            let week_minutes =
                calc_duration_in_range(&filtered, week_start, next_week_start, now);
            let month_minutes = calc_duration_from(&filtered, month_start, now);

            print_status(project, &running, today_minutes, week_minutes, month_minutes, now);
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}

pub fn projects(file_path: &str, current_only: bool, no_quotes: bool) {
    match read_activities(file_path) {
        Ok(data) => {
            let mut project_set = std::collections::BTreeSet::new();
            for activity in &data.activities {
                if current_only {
