fn apply_date_filter(activities: &mut Vec<Activity>, filter: &DateFilter) {
    if filter.from.is_none() && filter.to.is_none() {
        return;
    }
    activities.retain(|a| {
        let date = a.start.date();
        let from_ok = filter.from.map_or(true, |f| date >= f);
        let to_ok = filter.to.map_or(true, |t| date <= t);
        from_ok && to_ok
    });
}

/// Get unique (project, description) pairs ordered from most recent (index 0)
fn get_unique_recent_activities(
    activities: &[Activity],
    max: usize,
) -> Vec<(usize, &Activity)> {
    let mut seen = std::collections::HashSet::new();
    let mut unique: Vec<&Activity> = Vec::new();

    for activity in activities.iter().rev() {
        let key = (activity.project.clone(), activity.description.clone());
        if !seen.contains(&key) {
            seen.insert(key);
            unique.push(activity);
            if unique.len() >= max {
                break;
            }
        }
    }

    unique.iter().enumerate().map(|(i, a)| (i, *a)).collect()
}

fn activity_duration_minutes(activity: &Activity, now: NaiveDateTime) -> i64 {
    let end = activity.end.unwrap_or(now);
    end.signed_duration_since(activity.start)
        .num_minutes()
        .max(0)
}

fn is_multi_day(activity: &Activity) -> bool {
    match activity.end {
        Some(end) => end.date() != activity.start.date(),
        None => false,
    }
}

