fn print_report(activities: &[Activity], now: NaiveDateTime) {
    let mut project_map: BTreeMap<String, BTreeMap<String, i64>> = BTreeMap::new();

    for activity in activities {
        let minutes = activity_duration_minutes(activity, now);
        *project_map
            .entry(activity.project.clone())
            .or_default()
            .entry(activity.description.clone())
            .or_insert(0) += minutes;
    }

    if project_map.is_empty() {
        return;
    }

    let total_minutes: i64 = project_map
        .values()
        .flat_map(|tasks| tasks.values())
        .sum();

    // Find max label width (considering 4-space indent for tasks)
    let max_label_width = project_map
        .iter()
        .flat_map(|(proj, tasks)| {
            let mut widths = vec![proj.chars().count()];
            widths.extend(tasks.keys().map(|t| 4 + t.chars().count()));
            widths
        })
        .chain(std::iter::once("Total".len()))
        .max()
        .unwrap_or(5);

    // Find max duration width
    let max_dur_width = {
        let mut all_minutes: Vec<i64> = project_map
            .values()
            .flat_map(|tasks| tasks.values())
            .cloned()
            .collect();
        let project_totals: Vec<i64> = project_map
            .values()
            .map(|tasks| tasks.values().sum())
            .collect();
        all_minutes.extend(project_totals);
        all_minutes.push(total_minutes);
        all_minutes
            .iter()
            .map(|&m| format_duration(m).len())
            .max()
            .unwrap_or(3)
    };

    for (project, tasks) in &project_map {
        let project_total: i64 = tasks.values().sum();
        let project_dur = format_duration(project_total);
        let dots = max_label_width - project.chars().count();
        println!(
            "\x1b[1m{}{} {}\x1b[0m",
            project,
            ".".repeat(dots),
            rjust(&project_dur, max_dur_width)
        );

        for (task, &minutes) in tasks {
            let task_dur = format_duration(minutes);
            let indent_task = format!("    {}", task);
            let dots = max_label_width - indent_task.chars().count();
            println!(
                "{}{} {}",
                indent_task,
                ".".repeat(dots),
                rjust(&task_dur, max_dur_width)
            );
        }
        println!();
    }

    let total_dur = format_duration(total_minutes);
    let dots = max_label_width - "Total".len();
    println!(
        "\x1b[1m{}{} {}\x1b[0m",
        "Total",
        ".".repeat(dots),
        rjust(&total_dur, max_dur_width)
    );
}

fn rjust(s: &str, width: usize) -> String {
    let len = s.chars().count();
    if len >= width {
        s.to_string()
    } else {
        format!("{}{}", " ".repeat(width - len), s)
    }
}

fn calc_duration_in_range(
    activities: &[&Activity],
    from: NaiveDateTime,
    to: NaiveDateTime,
    now: NaiveDateTime,
) -> i64 {
    let mut total = 0i64;
    for activity in activities {
        let start = activity.start;
        let end = activity.end.unwrap_or(now);

        if end <= from || start >= to {
            continue;
        }

        let effective_start = start.max(from);
        let effective_end = end.min(to);

        if effective_end > effective_start {
            total += (effective_end - effective_start).num_minutes();
        }
    }
    total
}

fn calc_duration_from(activities: &[&Activity], from: NaiveDateTime, now: NaiveDateTime) -> i64 {
    let mut total = 0i64;
    for activity in activities {
        let start = activity.start;
        let end = activity.end.unwrap_or(now);

        if end <= from {
            continue;
        }

        let effective_start = start.max(from);
        if end > effective_start {
            total += (end - effective_start).num_minutes();
        }
    }
    total
}

fn print_status(
    project: Option<&str>,
