        .iter()
        .map(|(_, a)| a.project.chars().count())
        .max()
        .unwrap_or(7)
        .max(7);

    // Header
    let hash_col = pad_nbsp(" #", idx_width);
    let desc_col = pad_nbsp("Description", desc_width);
    let proj_col = pad_nbsp("Project", proj_width);
    println!(
        "\x1b[4m{}\x1b[0m \x1b[4m{}\x1b[0m \x1b[4m{}\x1b[0m ",
        hash_col, desc_col, proj_col
    );

    for (idx, activity) in activities {
        let idx_str = format!("[{}]", idx);
        let idx_padded = pad_nbsp(&idx_str, idx_width);
        let desc_padded = pad_nbsp(&activity.description, desc_width);
        let proj_padded = pad_nbsp(&activity.project, proj_width);
        println!("{} {} {} ", idx_padded, desc_padded, proj_padded);
    }
}

fn print_current_activities(activities: &[&Activity]) {
    let now = now_datetime();
    let desc_width = activities
        .iter()
        .map(|a| a.description.chars().count())
        .max()
        .unwrap_or(11)
        .max(11);
    let proj_width = activities
        .iter()
        .map(|a| a.project.chars().count())
        .max()
        .unwrap_or(7)
        .max(7);
    let dur_width = activities
        .iter()
        .map(|a| format_duration(activity_duration_minutes(a, now)).len())
        .max()
        .unwrap_or(8)
        .max(8);

