    let mut errors = Vec::new();
    for (i, line) in content.lines().enumerate() {
        let line_num = i + 1;
        if line.trim().is_empty() {
            continue;
        }
        if let Err(e) = crate::activity::parse_activity(line, line_num) {
            errors.push((line_num, line.to_string(), e));
        }
    }

    if errors.is_empty() {
        println!("All lines in the file have been successfully parsed as activities.");
    } else {
        println!("Found {} line(s) with parsing errors", errors.len());
        println!();
        for (_, line, err) in &errors {
