            std::process::exit(1);
        }
    }
}

pub fn edit(file_path: &str, editor: Option<&str>) {
    match editor {
        Some(ed) => {
            let status = std::process::Command::new(ed).arg(file_path).status();
            if let Err(e) = status {
                eprintln!("Error: Could not open editor: {}", e);
                std::process::exit(1);
            }
        }
        None => {
            eprintln!(
                "Error: No editor specified. Use -e option or set EDITOR environment variable."
            );
            std::process::exit(1);
        }
    }
}

