use chrono::{Local, NaiveDate, NaiveDateTime, NaiveTime, Datelike, Duration};
use std::collections::BTreeMap;

use crate::activity::{Activity, format_duration, round_datetime};
use crate::file_handler::{read_activities, write_activities, append_activity};
use crate::DateFilter;

// Non-breaking space character (U+00A0)
const NBSP: char = '\u{00A0}';

fn now_datetime() -> NaiveDateTime {
    Local::now().naive_local()
}

fn with_time_override(time: Option<NaiveTime>) -> NaiveDateTime {
    match time {
        Some(t) => {
            let today = Local::now().date_naive();
            NaiveDateTime::new(today, t)
        }
        None => now_datetime(),
    }
}

/// Pad a string with non-breaking spaces to the given width
fn pad_nbsp(s: &str, width: usize) -> String {
    let len = s.chars().count();
    if len >= width {
        s.to_string()
    } else {
        let padding: String = std::iter::repeat(NBSP).take(width - len).collect();
        format!("{}{}", s, padding)
    }
}

pub fn start(file_path: &str, description: &str, project: &str, time: Option<NaiveTime>) {
    let now = with_time_override(time);

    match read_activities(file_path) {
        Ok(mut data) => {
            for activity in data.activities.iter_mut() {
                if activity.is_running() {
                    activity.end = Some(now);
                    print_stopped(activity);
                }
            }
            let new_activity = Activity::new(project.to_string(), description.to_string(), now);
            data.activities.push(new_activity.clone());
            if let Err(e) = write_activities(file_path, &data.activities) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
            print_started(&new_activity);
        }
        Err(_) => {
            let new_activity = Activity::new(project.to_string(), description.to_string(), now);
            if let Err(e) = append_activity(file_path, &new_activity) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
            print_started(&new_activity);
        }
    }
}

pub fn stop(file_path: &str, time: Option<NaiveTime>) {
    let now = with_time_override(time);

    match read_activities(file_path) {
        Ok(mut data) => {
            let mut modified = false;
            for activity in data.activities.iter_mut() {
                if activity.is_running() {
                    activity.end = Some(now);
                    print_stopped(activity);
                    modified = true;
                }
            }
            if modified {
                if let Err(e) = write_activities(file_path, &data.activities) {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                }
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}

pub fn cancel(file_path: &str) {
    match read_activities(file_path) {
        Ok(mut data) => {
            let mut to_remove = Vec::new();
            for (i, activity) in data.activities.iter().enumerate() {
                if activity.is_running() {
                    print_canceled(activity);
                    to_remove.push(i);
                }
            }
            if !to_remove.is_empty() {
                for i in to_remove.iter().rev() {
                    data.activities.remove(*i);
                }
                if let Err(e) = write_activities(file_path, &data.activities) {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                }
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}

