        None => {
            print!("\x1b[3m Status for \x1b[0m\x1b[1mALL\x1b[0m\x1b[3m projects \x1b[0m\x1b[2m======= \x1b[0m\n");
        }
    }

    // NOW line
    if running.is_empty() {
        print!("\x1b[0m\x1b[2;3m\n  NOW: \x1b[0m\x1b[1m NO Activity\n\n");
    } else {
        let activity = running[0];
