def cmd_status(file_path, project_filter):
    now = now_dt()
    today = date.today()

    try:
        activities, _ = read_activities(file_path)

        if project_filter:
            filtered = [a for a in activities if a.project == project_filter]
        else:
            filtered = activities

        running = [a for a in filtered if a.is_running()]

        today_start = datetime.combine(today, time_type(0, 0))
        tomorrow_start = today_start + timedelta(days=1)

        weekday = today.weekday()  # 0=Monday
        monday = today - timedelta(days=weekday)
        week_start = datetime.combine(monday, time_type(0, 0))
        next_week_start = week_start + timedelta(days=7)

        month_start = datetime.combine(date(today.year, today.month, 1), time_type(0, 0))

        today_minutes = calc_duration_in_range(filtered, today_start, tomorrow_start, now)
        week_minutes = calc_duration_in_range(filtered, week_start, next_week_start, now)
        month_minutes = calc_duration_from(filtered, month_start, now)

        print_status(project_filter, running, today_minutes, week_minutes, month_minutes, now)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

def calc_duration_in_range(activities, from_dt, to_dt, now):
    total = 0
    for a in activities:
        start = a.start
        end = a.end or now
        if end <= from_dt or start >= to_dt:
            continue
        effective_start = max(start, from_dt)
        effective_end = min(end, to_dt)
        if effective_end > effective_start:
            total += int((effective_end - effective_start).total_seconds() // 60)
    return total

def calc_duration_from(activities, from_dt, now):
    total = 0
    for a in activities:
        start = a.start
        end = a.end or now
        if end <= from_dt:
            continue
        effective_start = max(start, from_dt)
        if end > effective_start:
            total += int((end - effective_start).total_seconds() // 60)
    return total

