#!/usr/bin/env python3
"""Bartib - A simple timetracker"""

import argparse
import sys
import os
import re
from datetime import datetime, date, timedelta, time as time_type
from collections import OrderedDict

# Non-breaking space
NBSP = '\u00A0'

def pad_nbsp(s, width):
    """Pad string with non-breaking spaces to the given width."""
    slen = len(s)
    if slen >= width:
        return s
    return s + NBSP * (width - slen)

def format_duration(minutes):
    """Format duration in minutes to human-readable string."""
    minutes = max(0, int(minutes))
    if minutes < 1:
        return "<1m"
    hours = minutes // 60
    mins = minutes % 60
    if hours == 0:
        return f"{mins}m"
    elif mins == 0:
        return f"{hours}h 00m"
    else:
        return f"{hours}h {mins:02d}m"

def now_dt():
    return datetime.now().replace(second=0, microsecond=0)

def today_date():
    return date.today()

def parse_datetime(s):
    """Parse datetime string in format YYYY-MM-DD HH:MM"""
    try:
        return datetime.strptime(s.strip(), "%Y-%m-%d %H:%M")
    except ValueError:
        return None

def round_datetime(dt, round_minutes):
    """Round datetime to nearest round_minutes interval."""
    total_seconds = int(dt.timestamp())
    round_seconds = round_minutes * 60
    rounded = ((total_seconds + round_seconds // 2) // round_seconds) * round_seconds
    return datetime.fromtimestamp(rounded).replace(second=0, microsecond=0)

class Activity:
    def __init__(self, project, description, start, end=None, line_number=None):
        self.project = project
        self.description = description
        self.start = start
        self.end = end
        self.line_number = line_number

    def is_running(self):
        return self.end is None

    def duration_minutes(self):
        end = self.end or now_dt()
        delta = end - self.start
        return max(0, int(delta.total_seconds() // 60))

    def to_file_string(self):
        start_str = self.start.strftime("%Y-%m-%d %H:%M")
        if self.end:
            end_str = self.end.strftime("%Y-%m-%d %H:%M")
            return f"{start_str} - {end_str} | {self.project} | {self.description}"
        else:
            return f"{start_str} | {self.project} | {self.description}"

def parse_activity(line, line_number):
    """Parse an activity line. Returns (Activity, None) or (None, error_string)."""
    line = line.strip()
    if not line:
        return None, "empty line"

    parts = line.split(" | ", 2)
    if len(parts) != 3:
        return None, f"could not parse activity (Line: {line_number})"

    time_part, project, description = parts[0].strip(), parts[1].strip(), parts[2].strip()

    if " - " in time_part:
        time_parts = time_part.split(" - ", 1)
        if len(time_parts) != 2:
            return None, f"could not parse activity (Line: {line_number})"
        start = parse_datetime(time_parts[0])
        end = parse_datetime(time_parts[1])
        if start is None or end is None:
            return None, f"could not parse activity (Line: {line_number})"
        return Activity(project, description, start, end, line_number), None
    else:
        start = parse_datetime(time_part)
        if start is None:
            return None, f"could not parse activity (Line: {line_number})"
        return Activity(project, description, start, None, line_number), None

def read_activities(file_path):
    """Read activities from file. Returns (activities, errors)."""
    try:
        with open(file_path, 'r') as f:
            content = f.read()
    except FileNotFoundError:
        raise Exception(f"Could not read from file: {file_path}\n\nCaused by:\n    No such file or directory (os error 2)")
    except IOError as e:
        raise Exception(f"Could not read from file: {file_path}\n\nCaused by:\n    {e}")

    activities = []
    errors = []
    for i, line in enumerate(content.split('\n')):
        line_num = i + 1
        if not line.strip():
            continue
        activity, err = parse_activity(line, line_num)
        if activity:
            activities.append(activity)
        else:
            errors.append((line_num, line, err))

    return activities, errors

def write_activities(file_path, activities):
    """Write activities to file."""
    content = '\n'.join(a.to_file_string() for a in activities)
    if content:
        content += '\n'
    with open(file_path, 'w') as f:
        f.write(content)

def append_activity(file_path, activity):
    """Append a single activity to file."""
    with open(file_path, 'a') as f:
        f.write(activity.to_file_string() + '\n')

def get_file_path(args):
    """Get file path from args or env."""
    if hasattr(args, 'file') and args.file:
        return args.file
    fp = os.environ.get('BARTIB_FILE')
    if fp:
        return fp
    return None

def with_time_override(time_str):
    """Get current datetime, optionally overriding the time part."""
    if time_str:
        try:
            t = datetime.strptime(time_str, "%H:%M").time()
            today = date.today()
            return datetime.combine(today, t)
        except ValueError:
            pass
    return now_dt()

def get_unique_recent_activities(activities, max_count=None):
    """Get unique (project, description) pairs, indexed from most recent (0)."""
    seen = set()
    unique = []
    for a in reversed(activities):
        key = (a.project, a.description)
        if key not in seen:
            seen.add(key)
            unique.append(a)
            if max_count is not None and len(unique) >= max_count:
                break
    return list(enumerate(unique))

def apply_date_filter(activities, from_date=None, to_date=None):
    """Filter activities by date range."""
    if from_date is None and to_date is None:
        return activities
    result = []
    for a in activities:
        d = a.start.date()
        if from_date and d < from_date:
            continue
        if to_date and d > to_date:
            continue
        result.append(a)
    return result

def is_multi_day(activity):
    """Check if activity spans multiple days."""
    if activity.end is None:
        return False
    return activity.end.date() != activity.start.date()

def activity_duration_minutes(activity, now=None):
    """Get activity duration in minutes."""
    if now is None:
        now = now_dt()
    end = activity.end or now
    delta = end - activity.start
    return max(0, int(delta.total_seconds() // 60))

def rjust(s, width):
    """Right-justify string."""
    if len(s) >= width:
        return s
    return ' ' * (width - len(s)) + s

