def build_date_filter(args):
    """Build from/to date filter from arguments."""
    today = date.today()

    if getattr(args, 'today', False):
        return today, today
    if getattr(args, 'yesterday', False):
        yesterday = today - timedelta(days=1)
        return yesterday, yesterday
    if getattr(args, 'current_week', False):
        weekday = today.weekday()  # 0=Monday
        monday = today - timedelta(days=weekday)
        sunday = monday + timedelta(days=6)
        return monday, sunday
    if getattr(args, 'last_week', False):
        weekday = today.weekday()
        this_monday = today - timedelta(days=weekday)
        last_monday = this_monday - timedelta(days=7)
        last_sunday = last_monday + timedelta(days=6)
        return last_monday, last_sunday

    from_date = None
    to_date = None

    if getattr(args, 'date', None):
        try:
            d = datetime.strptime(args.date, "%Y-%m-%d").date()
            return d, d
        except ValueError:
            pass

    if getattr(args, 'from_date', None):
        try:
            from_date = datetime.strptime(args.from_date, "%Y-%m-%d").date()
        except ValueError:
            pass

    if getattr(args, 'to_date', None):
        try:
            to_date = datetime.strptime(args.to_date, "%Y-%m-%d").date()
        except ValueError:
            pass

    return from_date, to_date

def parse_round(round_str):
    """Parse round string like '15m' or '4h' to minutes."""
    if round_str is None:
        return None
    if round_str.endswith('m'):
        try:
            return int(round_str[:-1])
        except ValueError:
            return None
    elif round_str.endswith('h'):
        try:
            return int(round_str[:-1]) * 60
        except ValueError:
            return None
    return None

