def make_parser():
    parser = argparse.ArgumentParser(
        prog='bartib',
        description='A simple timetracker',
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="To get help for a specific subcommand, run `bartib [SUBCOMMAND] --help`.\nTo get started, view the `start` help with `bartib start --help`"
    )
    parser.add_argument('--version', '-V', action='version', version='bartib 1.1.0')
    parser.add_argument('-f', metavar='FILE', dest='file', 
                       default=os.environ.get('BARTIB_FILE'),
                       help='the file in which bartib tracks all the activities [env: BARTIB_FILE=]')

    subparsers = parser.add_subparsers(dest='command')

    # cancel
    subparsers.add_parser('cancel', help='cancels all currently running activities')

    # change
    p_change = subparsers.add_parser('change', help='changes the current activity')
    p_change.add_argument('-d', '--description', metavar='DESCRIPTION', help='the description of the new activity')
    p_change.add_argument('-p', '--project', metavar='PROJECT', help='the project to which the new activity belongs')
    p_change.add_argument('-t', '--time', metavar='TIME', help='the time for changing the activity status (HH:MM)')

    # check
    subparsers.add_parser('check', help='checks file and reports parsing errors')

    # continue
    p_continue = subparsers.add_parser('continue', help='continues a previous activity')
    p_continue.add_argument('number', metavar='NUMBER', nargs='?', type=int, default=0,
                            help='the number of the activity to continue (see subcommand `last`) [default: 0]')
    p_continue.add_argument('-d', '--description', metavar='DESCRIPTION', help='the description of the new activity')
    p_continue.add_argument('-p', '--project', metavar='PROJECT', help='the project to which the new activity belongs')
    p_continue.add_argument('-t', '--time', metavar='TIME', help='the time for changing the activity status (HH:MM)')

    # current
    subparsers.add_parser('current', help='lists all currently running activities')

    # edit
    p_edit = subparsers.add_parser('edit', help='opens the activity log in an editor')
    p_edit.add_argument('-e', metavar='editor', dest='editor',
                       default=os.environ.get('EDITOR'),
                       help='the command to start your preferred text editor [env: EDITOR=]')

    # last
    p_last = subparsers.add_parser('last', help='displays the descriptions and projects of recent activities')
    p_last.add_argument('-n', '--number', metavar='NUMBER', type=int, default=10,
