    p_report.add_argument('-p', '--project', metavar='PROJECT', help='do report activities for this project only')
    p_report.add_argument('--round', metavar='round', help='rounds the start and end time to the nearest duration. Durations can be in minutes or hours. E.g. 15m or 4h')
    p_report.add_argument('--to', metavar='TO_DATE', dest='to_date', help='end of date range (inclusive)')

    # sanity
    subparsers.add_parser('sanity', help='checks sanity of bartib log')

    # search
    p_search = subparsers.add_parser('search', help='search for existing descriptions and projects')
    p_search.add_argument('search_term', metavar='SEARCH_TERM', nargs='?', default='',
                         help="the search term [default: '']")

    # start
    p_start = subparsers.add_parser('start', help='starts a new activity')
    p_start.add_argument('-d', '--description', metavar='DESCRIPTION', required=True,
                        help='the description of the new activity')
    p_start.add_argument('-p', '--project', metavar='PROJECT', required=True,
                        help='the project to which the new activity belongs')
    p_start.add_argument('-t', '--time', metavar='TIME', help='the time for changing the activity status (HH:MM)')

    # status
    p_status = subparsers.add_parser('status', help='shows current status and time reports for today, current week, and current month')
    p_status.add_argument('-p', '--project', metavar='PROJECT', help='show status for this project only')

    # stop
    p_stop = subparsers.add_parser('stop', help='stops all currently running activities')
    p_stop.add_argument('-t', '--time', metavar='TIME', help='the time for changing the activity status (HH:MM)')

    return parser

def main():
    parser = make_parser()
    args = parser.parse_args()

    if args.command is None:
        parser.print_help()
        sys.exit(0)

    file_path = args.file if hasattr(args, 'file') else None

    # Commands that don't need a file path
    if args.command == 'help':
        parser.print_help()
        return

    # Commands that need a file path
    if file_path is None:
        print("Error: Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable", file=sys.stderr)
