        cmd_report(file_path, args)
    elif args.command == 'status':
        cmd_status(file_path, args.project)
    elif args.command == 'projects':
        cmd_projects(file_path, args.current, args.no_quotes)
    elif args.command == 'search':
        cmd_search(file_path, args.search_term)
    elif args.command == 'check':
        cmd_check(file_path)
    elif args.command == 'sanity':
        cmd_sanity(file_path)
    elif args.command == 'continue':
        cmd_continue(file_path, args.number, args.description, args.project, args.time)
    elif args.command == 'edit':
        cmd_edit(file_path, args.editor)

if __name__ == '__main__':
    main()
