def print_started(activity):
    print(f'Started activity: "{activity.description}" ({activity.project}) at {activity.start.strftime("%Y-%m-%d %H:%M")}')

def print_stopped(activity):
    duration = format_duration(activity.duration_minutes())
    print(f'Stopped activity: "{activity.description}" ({activity.project}) started at {activity.start.strftime("%Y-%m-%d %H:%M")} ({duration})')

def print_canceled(activity):
    print(f'Canceled activity: "{activity.description}" ({activity.project}) started at {activity.start.strftime("%Y-%m-%d %H:%M")}')

def print_changed(activity):
    print(f'Changed activity: "{activity.description}" ({activity.project}) started at {activity.start.strftime("%Y-%m-%d %H:%M")}')

