def make_parser():
    parser = argparse.ArgumentParser(
        prog='bartib',
        description='A simple timetracker',
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="To get help for a specific subcommand, run `bartib [SUBCOMMAND] --help`.\nTo get started, view the `start` help with `bartib start --help`"
    )
    parser.add_argument('--version', '-V', action='version', version='bartib 1.1.0')
    parser.add_argument('-f', metavar='FILE', dest='file', 
                       default=os.environ.get('BARTIB_FILE'),
                       help='the file in which bartib tracks all the activities [env: BARTIB_FILE=]')

    subparsers = parser.add_subparsers(dest='command')

    # cancel
    subparsers.add_parser('cancel', help='cancels all currently running activities')

    # change
    p_change = subparsers.add_parser('change', help='changes the current activity')
    p_change.add_argument('-d', '--description', metavar='DESCRIPTION', help='the description of the new activity')
    p_change.add_argument('-p', '--project', metavar='PROJECT', help='the project to which the new activity belongs')
    p_change.add_argument('-t', '--time', metavar='TIME', help='the time for changing the activity status (HH:MM)')

    # check
    subparsers.add_parser('check', help='checks file and reports parsing errors')

    # continue
    p_continue = subparsers.add_parser('continue', help='continues a previous activity')
    p_continue.add_argument('number', metavar='NUMBER', nargs='?', type=int, default=0,
                            help='the number of the activity to continue (see subcommand `last`) [default: 0]')
    p_continue.add_argument('-d', '--description', metavar='DESCRIPTION', help='the description of the new activity')
    p_continue.add_argument('-p', '--project', metavar='PROJECT', help='the project to which the new activity belongs')
    p_continue.add_argument('-t', '--time', metavar='TIME', help='the time for changing the activity status (HH:MM)')

    # current
    subparsers.add_parser('current', help='lists all currently running activities')

    # edit
    p_edit = subparsers.add_parser('edit', help='opens the activity log in an editor')
    p_edit.add_argument('-e', metavar='editor', dest='editor',
                       default=os.environ.get('EDITOR'),
                       help='the command to start your preferred text editor [env: EDITOR=]')

    # last
    p_last = subparsers.add_parser('last', help='displays the descriptions and projects of recent activities')
    p_last.add_argument('-n', '--number', metavar='NUMBER', type=int, default=10,
                       help='maximum number of lines to display [default: 10]')

    # list
    p_list = subparsers.add_parser('list', help='list recent activities')
    p_list.add_argument('--current_week', action='store_true', help='show activities of the current week')
    p_list.add_argument('--last_week', action='store_true', help='show activities of the last week')
    p_list.add_argument('--no_grouping', action='store_true', help='do not group activities by date in list')
    p_list.add_argument('--today', action='store_true', help='show activities of the current day')
    p_list.add_argument('--yesterday', action='store_true', help="show yesterdays' activities")
    p_list.add_argument('-d', '--date', metavar='DATE', help='show activities of a certain date only')
    p_list.add_argument('--from', metavar='FROM_DATE', dest='from_date', help='begin of date range (inclusive)')
    p_list.add_argument('-n', '--number', metavar='NUMBER', type=int, help='maximum number of activities to display')
    p_list.add_argument('-p', '--project', metavar='PROJECT', help='do list activities for this project only')
    p_list.add_argument('--round', metavar='round', help='rounds the start and end time to the nearest duration. Durations can be in minutes or hours. E.g. 15m or 4h')
    p_list.add_argument('--to', metavar='TO_DATE', dest='to_date', help='end of date range (inclusive)')

    # projects
    p_projects = subparsers.add_parser('projects', help='list all projects')
    p_projects.add_argument('-c', '--current', action='store_true', help='prints currently running projects only')
    p_projects.add_argument('-n', '--no-quotes', action='store_true', dest='no_quotes', help='prints projects without quotes')

    # report
    p_report = subparsers.add_parser('report', help='reports duration of tracked activities')
    p_report.add_argument('--current_week', action='store_true', help='show activities of the current week')
    p_report.add_argument('--last_week', action='store_true', help='show activities of the last week')
    p_report.add_argument('--today', action='store_true', help='show activities of the current day')
    p_report.add_argument('--yesterday', action='store_true', help="show yesterdays' activities")
    p_report.add_argument('-d', '--date', metavar='DATE', help='show activities of a certain date only')
    p_report.add_argument('--from', metavar='FROM_DATE', dest='from_date', help='begin of date range (inclusive)')
    p_report.add_argument('-p', '--project', metavar='PROJECT', help='do report activities for this project only')
    p_report.add_argument('--round', metavar='round', help='rounds the start and end time to the nearest duration. Durations can be in minutes or hours. E.g. 15m or 4h')
    p_report.add_argument('--to', metavar='TO_DATE', dest='to_date', help='end of date range (inclusive)')

    # sanity
    subparsers.add_parser('sanity', help='checks sanity of bartib log')

    # search
    p_search = subparsers.add_parser('search', help='search for existing descriptions and projects')
    p_search.add_argument('search_term', metavar='SEARCH_TERM', nargs='?', default='',
                         help="the search term [default: '']")

    # start
    p_start = subparsers.add_parser('start', help='starts a new activity')
    p_start.add_argument('-d', '--description', metavar='DESCRIPTION', required=True,
                        help='the description of the new activity')
    p_start.add_argument('-p', '--project', metavar='PROJECT', required=True,
                        help='the project to which the new activity belongs')
    p_start.add_argument('-t', '--time', metavar='TIME', help='the time for changing the activity status (HH:MM)')

    # status
    p_status = subparsers.add_parser('status', help='shows current status and time reports for today, current week, and current month')
