def cmd_start(file_path, description, project, time_str):
    now = with_time_override(time_str)

    activities_written = False
    try:
        activities, _ = read_activities(file_path)
        for a in activities:
            if a.is_running():
                a.end = now
                print_stopped(a)

        new_activity = Activity(project, description, now)
        activities.append(new_activity)
        write_activities(file_path, activities)
        activities_written = True
        print_started(new_activity)
    except Exception as e:
        if not activities_written:
            # File doesn't exist yet
            new_activity = Activity(project, description, now)
            try:
                append_activity(file_path, new_activity)
                print_started(new_activity)
            except Exception as e2:
                print(f"Error: {e2}", file=sys.stderr)
                sys.exit(1)
        else:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)

def cmd_stop(file_path, time_str):
    now = with_time_override(time_str)
    try:
        activities, _ = read_activities(file_path)
        modified = False
        for a in activities:
            if a.is_running():
                a.end = now
                print_stopped(a)
                modified = True
        if modified:
            write_activities(file_path, activities)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

def cmd_cancel(file_path):
    try:
        activities, _ = read_activities(file_path)
        to_remove = []
        for i, a in enumerate(activities):
            if a.is_running():
                print_canceled(a)
                to_remove.append(i)
        if to_remove:
            for i in reversed(to_remove):
                del activities[i]
            write_activities(file_path, activities)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

def cmd_change(file_path, description, project, time_str):
    try:
        activities, _ = read_activities(file_path)
        modified = False
        for a in activities:
            if a.is_running():
                if description:
                    a.description = description
                if project:
                    a.project = project
                if time_str:
                    try:
                        t = datetime.strptime(time_str, "%H:%M").time()
                        a.start = datetime.combine(a.start.date(), t)
                    except ValueError:
                        pass
                print_changed(a)
                modified = True
        if modified:
            write_activities(file_path, activities)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

def cmd_current(file_path):
    try:
        activities, _ = read_activities(file_path)
        running = [a for a in activities if a.is_running()]
        if not running:
            print("No Activity is currently running")
            return
        print_current_activities(running)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
