        print_last_table(unique)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

def build_date_filter(args):
    """Build from/to date filter from arguments."""
    today = date.today()

    if getattr(args, 'today', False):
        return today, today
    if getattr(args, 'yesterday', False):
        yesterday = today - timedelta(days=1)
        return yesterday, yesterday
    if getattr(args, 'current_week', False):
        weekday = today.weekday()  # 0=Monday
        monday = today - timedelta(days=weekday)
        sunday = monday + timedelta(days=6)
        return monday, sunday
    if getattr(args, 'last_week', False):
        weekday = today.weekday()
        this_monday = today - timedelta(days=weekday)
        last_monday = this_monday - timedelta(days=7)
        last_sunday = last_monday + timedelta(days=6)
        return last_monday, last_sunday

    from_date = None
    to_date = None

    if getattr(args, 'date', None):
        try:
            d = datetime.strptime(args.date, "%Y-%m-%d").date()
            return d, d
        except ValueError:
            pass

    if getattr(args, 'from_date', None):
        try:
            from_date = datetime.strptime(args.from_date, "%Y-%m-%d").date()
        except ValueError:
            pass

    if getattr(args, 'to_date', None):
        try:
            to_date = datetime.strptime(args.to_date, "%Y-%m-%d").date()
        except ValueError:
            pass

    return from_date, to_date

def parse_round(round_str):
    """Parse round string like '15m' or '4h' to minutes."""
    if round_str is None:
        return None
    if round_str.endswith('m'):
        try:
            return int(round_str[:-1])
        except ValueError:
            return None
    elif round_str.endswith('h'):
        try:
            return int(round_str[:-1]) * 60
        except ValueError:
            return None
    return None

def cmd_list(file_path, args):
    now = now_dt()
    from_date, to_date = build_date_filter(args)
    no_grouping = getattr(args, 'no_grouping', False)
    number = getattr(args, 'number', None)
    round_minutes = parse_round(getattr(args, 'round', None))
    project = getattr(args, 'project', None)

    try:
        activities, _ = read_activities(file_path)

        if project:
            activities = [a for a in activities if a.project == project]

        activities = apply_date_filter(activities, from_date, to_date)

        if number is not None:
            if len(activities) > number:
                activities = activities[len(activities)-number:]

        if round_minutes:
            for a in activities:
                a.start = round_datetime(a.start, round_minutes)
                if a.end:
                    a.end = round_datetime(a.end, round_minutes)

        print()
        if no_grouping:
            print_list_no_grouping(activities, now)
        else:
            print_list_grouped(activities, now)
        print()
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

def cmd_report(file_path, args):
    now = now_dt()
    from_date, to_date = build_date_filter(args)
    round_minutes = parse_round(getattr(args, 'round', None))
    project = getattr(args, 'project', None)

    try:
        activities, _ = read_activities(file_path)

        if project:
            activities = [a for a in activities if a.project == project]

        activities = apply_date_filter(activities, from_date, to_date)

        if round_minutes:
            for a in activities:
                a.start = round_datetime(a.start, round_minutes)
                if a.end:
                    a.end = round_datetime(a.end, round_minutes)

        print()
        print_report(activities, now)
        print()
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

def cmd_status(file_path, project_filter):
    now = now_dt()
    today = date.today()

    try:
        activities, _ = read_activities(file_path)

        if project_filter:
            filtered = [a for a in activities if a.project == project_filter]
        else:
            filtered = activities

        running = [a for a in filtered if a.is_running()]

        today_start = datetime.combine(today, time_type(0, 0))
        tomorrow_start = today_start + timedelta(days=1)

        weekday = today.weekday()  # 0=Monday
        monday = today - timedelta(days=weekday)
        week_start = datetime.combine(monday, time_type(0, 0))
        next_week_start = week_start + timedelta(days=7)

        month_start = datetime.combine(date(today.year, today.month, 1), time_type(0, 0))

        today_minutes = calc_duration_in_range(filtered, today_start, tomorrow_start, now)
        week_minutes = calc_duration_in_range(filtered, week_start, next_week_start, now)
        month_minutes = calc_duration_from(filtered, month_start, now)

        print_status(project_filter, running, today_minutes, week_minutes, month_minutes, now)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

def calc_duration_in_range(activities, from_dt, to_dt, now):
    total = 0
    for a in activities:
        start = a.start
        end = a.end or now
        if end <= from_dt or start >= to_dt:
            continue
        effective_start = max(start, from_dt)
        effective_end = min(end, to_dt)
        if effective_end > effective_start:
            total += int((effective_end - effective_start).total_seconds() // 60)
    return total

def calc_duration_from(activities, from_dt, now):
    total = 0
    for a in activities:
        start = a.start
        end = a.end or now
        if end <= from_dt:
            continue
        effective_start = max(start, from_dt)
        if end > effective_start:
            total += int((end - effective_start).total_seconds() // 60)
    return total

def cmd_projects(file_path, current_only, no_quotes):
    try:
        activities, _ = read_activities(file_path)
        projects = set()
        for a in activities:
            if current_only:
                if a.is_running():
                    projects.add(a.project)
            else:
                projects.add(a.project)
        for p in sorted(projects):
            if no_quotes:
                print(p)
            else:
                print(f'"{p}"')
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

def cmd_search(file_path, term):
    try:
        activities, _ = read_activities(file_path)
        term_lower = term.lower()
        unique = get_unique_recent_activities(activities)
        filtered = [(i, a) for i, a in unique 
                    if term_lower in a.description.lower() or term_lower in a.project.lower()]
        print_last_table(filtered)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

def cmd_check(file_path):
    try:
        with open(file_path, 'r') as f:
            content = f.read()
    except FileNotFoundError:
        print(f"Error: Could not read from file: {file_path}\n\nCaused by:\n    No such file or directory (os error 2)", file=sys.stderr)
        sys.exit(1)
    except IOError as e:
        print(f"Error: Could not read from file: {file_path}\n\nCaused by:\n    {e}", file=sys.stderr)
        sys.exit(1)

    errors = []
    for i, line in enumerate(content.split('\n')):
        line_num = i + 1
        if not line.strip():
            continue
        _, err = parse_activity(line, line_num)
        if err:
            errors.append((line_num, line, err))

    if not errors:
        print("All lines in the file have been successfully parsed as activities.")
    else:
        print(f"Found {len(errors)} line(s) with parsing errors")
        print()
        for _, line, err in errors:
            print(line)
            print(f"  -> {err}")

def cmd_sanity(file_path):
    try:
        activities, _ = read_activities(file_path)
        found_issues = False

        for i in range(1, len(activities)):
            prev = activities[i-1]
            curr = activities[i]

            if prev.end and curr.start < prev.end:
                line_num = curr.line_number or (i + 1)
                end_str = curr.end.strftime("%Y-%m-%d %H:%M") if curr.end else ""
                print("Activity started before another activity ended")
                print(f"{curr.description} (Started: {curr.start.strftime('%Y-%m-%d %H:%M')}, Ended: {end_str}, Line: {line_num})")
                print()
                found_issues = True

        if not found_issues:
            print("No unusual activities.")
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

def cmd_continue(file_path, number, description, project, time_str):
    now = with_time_override(time_str)

    try:
        activities, _ = read_activities(file_path)

        # Stop all currently running
        for a in activities:
            if a.is_running():
                a.end = now
                print_stopped(a)

        # Get unique activities
        unique = get_unique_recent_activities(activities)

        # Find the one to continue
        found = None
        for idx, a in unique:
            if idx == number:
                found = a
                break

        if found:
            desc = description or found.description
            proj = project or found.project
            new_activity = Activity(proj, desc, now)
            activities.append(new_activity)
            write_activities(file_path, activities)
            print_started(new_activity)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

def cmd_edit(file_path, editor):
    if not editor:
        print("Error: No editor specified. Use -e option or set EDITOR environment variable.", file=sys.stderr)
        sys.exit(1)
    os.execlp(editor, editor, file_path)

def print_started(activity):
    print(f'Started activity: "{activity.description}" ({activity.project}) at {activity.start.strftime("%Y-%m-%d %H:%M")}')

def print_stopped(activity):
    duration = format_duration(activity.duration_minutes())
    print(f'Stopped activity: "{activity.description}" ({activity.project}) started at {activity.start.strftime("%Y-%m-%d %H:%M")} ({duration})')

def print_canceled(activity):
    print(f'Canceled activity: "{activity.description}" ({activity.project}) started at {activity.start.strftime("%Y-%m-%d %H:%M")}')

def print_changed(activity):
    print(f'Changed activity: "{activity.description}" ({activity.project}) started at {activity.start.strftime("%Y-%m-%d %H:%M")}')

# ============================================================
# Argument parsing
# ============================================================

def make_parser():
    parser = argparse.ArgumentParser(
        prog='bartib',
        description='A simple timetracker',
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="To get help for a specific subcommand, run `bartib [SUBCOMMAND] --help`.\nTo get started, view the `start` help with `bartib start --help`"
    )
    parser.add_argument('--version', '-V', action='version', version='bartib 1.1.0')
    parser.add_argument('-f', metavar='FILE', dest='file', 
                       default=os.environ.get('BARTIB_FILE'),
                       help='the file in which bartib tracks all the activities [env: BARTIB_FILE=]')

    subparsers = parser.add_subparsers(dest='command')

    # cancel
    subparsers.add_parser('cancel', help='cancels all currently running activities')

    # change
    p_change = subparsers.add_parser('change', help='changes the current activity')
    p_change.add_argument('-d', '--description', metavar='DESCRIPTION', help='the description of the new activity')
    p_change.add_argument('-p', '--project', metavar='PROJECT', help='the project to which the new activity belongs')
    p_change.add_argument('-t', '--time', metavar='TIME', help='the time for changing the activity status (HH:MM)')

    # check
    subparsers.add_parser('check', help='checks file and reports parsing errors')

    # continue
    p_continue = subparsers.add_parser('continue', help='continues a previous activity')
    p_continue.add_argument('number', metavar='NUMBER', nargs='?', type=int, default=0,
                            help='the number of the activity to continue (see subcommand `last`) [default: 0]')
    p_continue.add_argument('-d', '--description', metavar='DESCRIPTION', help='the description of the new activity')
    p_continue.add_argument('-p', '--project', metavar='PROJECT', help='the project to which the new activity belongs')
    p_continue.add_argument('-t', '--time', metavar='TIME', help='the time for changing the activity status (HH:MM)')

    # current
    subparsers.add_parser('current', help='lists all currently running activities')

    # edit
    p_edit = subparsers.add_parser('edit', help='opens the activity log in an editor')
    p_edit.add_argument('-e', metavar='editor', dest='editor',
                       default=os.environ.get('EDITOR'),
                       help='the command to start your preferred text editor [env: EDITOR=]')

    # last
    p_last = subparsers.add_parser('last', help='displays the descriptions and projects of recent activities')
    p_last.add_argument('-n', '--number', metavar='NUMBER', type=int, default=10,
                       help='maximum number of lines to display [default: 10]')

    # list
    p_list = subparsers.add_parser('list', help='list recent activities')
    p_list.add_argument('--current_week', action='store_true', help='show activities of the current week')
    p_list.add_argument('--last_week', action='store_true', help='show activities of the last week')
    p_list.add_argument('--no_grouping', action='store_true', help='do not group activities by date in list')
    p_list.add_argument('--today', action='store_true', help='show activities of the current day')
    p_list.add_argument('--yesterday', action='store_true', help="show yesterdays' activities")
    p_list.add_argument('-d', '--date', metavar='DATE', help='show activities of a certain date only')
    p_list.add_argument('--from', metavar='FROM_DATE', dest='from_date', help='begin of date range (inclusive)')
    p_list.add_argument('-n', '--number', metavar='NUMBER', type=int, help='maximum number of activities to display')
    p_list.add_argument('-p', '--project', metavar='PROJECT', help='do list activities for this project only')
    p_list.add_argument('--round', metavar='round', help='rounds the start and end time to the nearest duration. Durations can be in minutes or hours. E.g. 15m or 4h')
    p_list.add_argument('--to', metavar='TO_DATE', dest='to_date', help='end of date range (inclusive)')

    # projects
    p_projects = subparsers.add_parser('projects', help='list all projects')
    p_projects.add_argument('-c', '--current', action='store_true', help='prints currently running projects only')
    p_projects.add_argument('-n', '--no-quotes', action='store_true', dest='no_quotes', help='prints projects without quotes')

    # report
    p_report = subparsers.add_parser('report', help='reports duration of tracked activities')
    p_report.add_argument('--current_week', action='store_true', help='show activities of the current week')
    p_report.add_argument('--last_week', action='store_true', help='show activities of the last week')
    p_report.add_argument('--today', action='store_true', help='show activities of the current day')
    p_report.add_argument('--yesterday', action='store_true', help="show yesterdays' activities")
    p_report.add_argument('-d', '--date', metavar='DATE', help='show activities of a certain date only')
    p_report.add_argument('--from', metavar='FROM_DATE', dest='from_date', help='begin of date range (inclusive)')
    p_report.add_argument('-p', '--project', metavar='PROJECT', help='do report activities for this project only')
    p_report.add_argument('--round', metavar='round', help='rounds the start and end time to the nearest duration. Durations can be in minutes or hours. E.g. 15m or 4h')
    p_report.add_argument('--to', metavar='TO_DATE', dest='to_date', help='end of date range (inclusive)')

    # sanity
    subparsers.add_parser('sanity', help='checks sanity of bartib log')

    # search
    p_search = subparsers.add_parser('search', help='search for existing descriptions and projects')
    p_search.add_argument('search_term', metavar='SEARCH_TERM', nargs='?', default='',
                         help="the search term [default: '']")

    # start
    p_start = subparsers.add_parser('start', help='starts a new activity')
    p_start.add_argument('-d', '--description', metavar='DESCRIPTION', required=True,
                        help='the description of the new activity')
    p_start.add_argument('-p', '--project', metavar='PROJECT', required=True,
                        help='the project to which the new activity belongs')
    p_start.add_argument('-t', '--time', metavar='TIME', help='the time for changing the activity status (HH:MM)')

    # status
    p_status = subparsers.add_parser('status', help='shows current status and time reports for today, current week, and current month')
    p_status.add_argument('-p', '--project', metavar='PROJECT', help='show status for this project only')

    # stop
    p_stop = subparsers.add_parser('stop', help='stops all currently running activities')
    p_stop.add_argument('-t', '--time', metavar='TIME', help='the time for changing the activity status (HH:MM)')

    return parser

def main():
    parser = make_parser()
    args = parser.parse_args()

    if args.command is None:
        parser.print_help()
        sys.exit(0)

    file_path = args.file if hasattr(args, 'file') else None

    # Commands that don't need a file path
    if args.command == 'help':
        parser.print_help()
        return

    # Commands that need a file path
    if file_path is None:
        print("Error: Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable", file=sys.stderr)
        sys.exit(1)

    if args.command == 'start':
        cmd_start(file_path, args.description, args.project, args.time)
    elif args.command == 'stop':
        cmd_stop(file_path, args.time)
    elif args.command == 'cancel':
        cmd_cancel(file_path)
    elif args.command == 'change':
        cmd_change(file_path, args.description, args.project, args.time)
    elif args.command == 'current':
        cmd_current(file_path)
    elif args.command == 'last':
        cmd_last(file_path, args.number)
    elif args.command == 'list':
        cmd_list(file_path, args)
    elif args.command == 'report':
        cmd_report(file_path, args)
    elif args.command == 'status':
        cmd_status(file_path, args.project)
    elif args.command == 'projects':
        cmd_projects(file_path, args.current, args.no_quotes)
    elif args.command == 'search':
        cmd_search(file_path, args.search_term)
    elif args.command == 'check':
        cmd_check(file_path)
    elif args.command == 'sanity':
        cmd_sanity(file_path)
    elif args.command == 'continue':
        cmd_continue(file_path, args.number, args.description, args.project, args.time)
    elif args.command == 'edit':
        cmd_edit(file_path, args.editor)

if __name__ == '__main__':
    main()
