#!/usr/bin/env python3
"""Bartib - A simple timetracker"""

import argparse
import sys
import os
from datetime import datetime, date, timedelta, time as time_type
from collections import OrderedDict

# Non-breaking space
NBSP = '\u00A0'

def pad_nbsp(s, width):
    """Pad string with non-breaking spaces to the given width."""
    slen = len(s)
    if slen >= width:
        return s
    return s + NBSP * (width - slen)

def format_duration(minutes):
    """Format duration in minutes to human-readable string."""
    minutes = max(0, int(minutes))
    if minutes < 1:
        return "<1m"
    hours = minutes // 60
    mins = minutes % 60
    if hours == 0:
        return f"{mins}m"
    elif mins == 0:
        return f"{hours}h 00m"
    else:
        return f"{hours}h {mins:02d}m"

def now_dt():
    return datetime.now().replace(second=0, microsecond=0)

def parse_datetime(s):
    """Parse datetime string in format YYYY-MM-DD HH:MM"""
    try:
        return datetime.strptime(s.strip(), "%Y-%m-%d %H:%M")
    except ValueError:
        return None

def round_datetime(dt, round_minutes):
    """Round datetime to nearest round_minutes interval."""
    import time as time_mod
    total_seconds = int(dt.timestamp())
    round_seconds = round_minutes * 60
    rounded = ((total_seconds + round_seconds // 2) // round_seconds) * round_seconds
    return datetime.fromtimestamp(rounded).replace(second=0, microsecond=0)

class Activity:
    def __init__(self, project, description, start, end=None, line_number=None):
        self.project = project
        self.description = description
        self.start = start
        self.end = end
        self.line_number = line_number

    def is_running(self):
        return self.end is None

    def duration_minutes(self):
        end = self.end or now_dt()
        delta = end - self.start
        return max(0, int(delta.total_seconds() // 60))

    def to_file_string(self):
        start_str = self.start.strftime("%Y-%m-%d %H:%M")
        if self.end:
            end_str = self.end.strftime("%Y-%m-%d %H:%M")
            return f"{start_str} - {end_str} | {self.project} | {self.description}"
        else:
            return f"{start_str} | {self.project} | {self.description}"

def parse_activity(line, line_number):
    """Parse an activity line. Returns (Activity, None) or (None, error_string)."""
    line = line.strip()
    if not line:
        return None, "empty line"

    parts = line.split(" | ", 2)
    if len(parts) != 3:
        return None, f"could not parse activity (Line: {line_number})"

    time_part, project, description = parts[0].strip(), parts[1].strip(), parts[2].strip()

    if " - " in time_part:
        time_parts = time_part.split(" - ", 1)
        if len(time_parts) != 2:
            return None, f"could not parse activity (Line: {line_number})"
        start = parse_datetime(time_parts[0])
        end = parse_datetime(time_parts[1])
        if start is None or end is None:
            return None, f"could not parse activity (Line: {line_number})"
        return Activity(project, description, start, end, line_number), None
    else:
        start = parse_datetime(time_part)
        if start is None:
            return None, f"could not parse activity (Line: {line_number})"
        return Activity(project, description, start, None, line_number), None

def read_activities(file_path):
    """Read activities from file. Returns (activities, errors)."""
    try:
        with open(file_path, 'r') as f:
            content = f.read()
    except FileNotFoundError:
        raise Exception(f"Could not read from file: {file_path}\n\nCaused by:\n    No such file or directory (os error 2)")
    except IOError as e:
        raise Exception(f"Could not read from file: {file_path}\n\nCaused by:\n    {e}")

    activities = []
    errors = []
    for i, line in enumerate(content.split('\n')):
        line_num = i + 1
        if not line.strip():
            continue
        activity, err = parse_activity(line, line_num)
        if activity:
            activities.append(activity)
        else:
            errors.append((line_num, line, err))

    return activities, errors

def write_activities(file_path, activities):
    """Write activities to file."""
    content = '\n'.join(a.to_file_string() for a in activities)
    if content:
        content += '\n'
    with open(file_path, 'w') as f:
        f.write(content)

def append_activity(file_path, activity):
    """Append a single activity to file."""
    with open(file_path, 'a') as f:
        f.write(activity.to_file_string() + '\n')

def with_time_override(time_str):
    """Get current datetime, optionally overriding the time part."""
    if time_str:
        try:
            t = datetime.strptime(time_str, "%H:%M").time()
            today = date.today()
            return datetime.combine(today, t)
        except ValueError:
            pass
    return now_dt()

def get_unique_recent_activities(activities, max_count=None):
    """Get unique (project, description) pairs, indexed from most recent (0)."""
    seen = set()
    unique = []
    for a in reversed(activities):
        key = (a.project, a.description)
        if key not in seen:
            seen.add(key)
            unique.append(a)
            if max_count is not None and len(unique) >= max_count:
                break
    # Return as [(index, activity)] where index 0 = most recent
    return list(enumerate(unique))

def apply_date_filter(activities, from_date=None, to_date=None):
    """Filter activities by date range."""
    if from_date is None and to_date is None:
        return activities
    result = []
    for a in activities:
        d = a.start.date()
        if from_date and d < from_date:
            continue
        if to_date and d > to_date:
            continue
        result.append(a)
    return result

def is_multi_day(activity):
    """Check if activity spans multiple days."""
    if activity.end is None:
        return False
    return activity.end.date() != activity.start.date()

def activity_duration_minutes(activity, now=None):
    """Get activity duration in minutes."""
    if now is None:
        now = now_dt()
    end = activity.end or now
    delta = end - activity.start
    return max(0, int(delta.total_seconds() // 60))

def rjust(s, width):
    """Right-justify string."""
    if len(s) >= width:
        return s
    return ' ' * (width - len(s)) + s

# ============================================================
# Print functions
# ============================================================

def print_last_table(indexed_activities):
    """Print the 'last' table output."""
    print()
    if not indexed_activities:
        return

    max_idx = max(i for i, _ in indexed_activities)
    idx_width = len(f"[{max_idx}]")

    desc_width = max((len(a.description) for _, a in indexed_activities), default=11)
    desc_width = max(desc_width, 11)  # "Description" = 11

    proj_width = max((len(a.project) for _, a in indexed_activities), default=7)
    proj_width = max(proj_width, 7)  # "Project" = 7

    # Header
    hash_col = pad_nbsp(" #", idx_width)
    desc_col = pad_nbsp("Description", desc_width)
    proj_col = pad_nbsp("Project", proj_width)
    print(f"\033[4m{hash_col}\033[0m \033[4m{desc_col}\033[0m \033[4m{proj_col}\033[0m ")

    # Display in REVERSE order (highest index = oldest, displayed first)
    for idx, activity in reversed(indexed_activities):
        idx_str = f"[{idx}]"
        idx_padded = pad_nbsp(idx_str, idx_width)
        desc_padded = pad_nbsp(activity.description, desc_width)
        proj_padded = pad_nbsp(activity.project, proj_width)
        print(f"{idx_padded} {desc_padded} {proj_padded} ")

def print_current_activities(activities):
    """Print currently running activities."""
    now = now_dt()
    desc_width = max((len(a.description) for a in activities), default=11)
    desc_width = max(desc_width, 11)
    proj_width = max((len(a.project) for a in activities), default=7)
    proj_width = max(proj_width, 7)
    dur_width = max((len(format_duration(activity_duration_minutes(a, now))) for a in activities), default=8)
    dur_width = max(dur_width, 8)

    print()
    started_at_col = pad_nbsp("Started At", 16)
    desc_col = pad_nbsp("Description", desc_width)
    proj_col = pad_nbsp("Project", proj_width)
    print(f"\033[4m{started_at_col}\033[0m \033[4m{desc_col}\033[0m \033[4m{proj_col}\033[0m \033[4mDuration\033[0m ")

    for a in activities:
        duration = format_duration(activity_duration_minutes(a, now))
        dur_padded = pad_nbsp(duration, dur_width)
        start_str = a.start.strftime("%Y-%m-%d %H:%M")
        desc_padded = pad_nbsp(a.description, desc_width)
        proj_padded = pad_nbsp(a.project, proj_width)
        print(f"{start_str} {desc_padded} {proj_padded} {dur_padded} ")

def _get_list_widths(activities, now):
    """Get column widths for list output."""
    desc_width = max((len(a.description) for a in activities), default=11) if activities else 11
    desc_width = max(desc_width, 11)
    proj_width = max((len(a.project) for a in activities), default=7) if activities else 7
    proj_width = max(proj_width, 7)
    dur_width = max((len(format_duration(activity_duration_minutes(a, now))) for a in activities), default=8) if activities else 8
    dur_width = max(dur_width, 8)
    has_multiday = any(is_multi_day(a) for a in activities)
    stopped_width = 16 if has_multiday else 7
    return desc_width, proj_width, dur_width, stopped_width

def _print_list_header_grouped(desc_width, proj_width, stopped_width):
    """Print list header for grouped mode (time-only started)."""
    started_col = pad_nbsp("Started", 7)
    stopped_col = pad_nbsp("Stopped", stopped_width)
    desc_col = pad_nbsp("Description", desc_width)
    proj_col = pad_nbsp("Project", proj_width)
    print(f"\033[4m{started_col}\033[0m \033[4m{stopped_col}\033[0m \033[4m{desc_col}\033[0m \033[4m{proj_col}\033[0m \033[4mDuration\033[0m ")

def _print_list_header_no_grouping(desc_width, proj_width, stopped_width):
    """Print list header for no_grouping mode (full date+time started)."""
    started_col = pad_nbsp("Started", 16)
    stopped_col = pad_nbsp("Stopped", stopped_width)
    desc_col = pad_nbsp("Description", desc_width)
    proj_col = pad_nbsp("Project", proj_width)
    print(f"\033[4m{started_col}\033[0m \033[4m{stopped_col}\033[0m \033[4m{desc_col}\033[0m \033[4m{proj_col}\033[0m \033[4mDuration\033[0m ")

def _get_stopped_str(activity):
    """Get stopped time string for an activity."""
    if activity.end is None:
        return "-"
    elif activity.end.date() != activity.start.date():
        return activity.end.strftime("%Y-%m-%d %H:%M")
    else:
        return activity.end.strftime("%H:%M")

def _print_list_row_grouped(activity, desc_width, proj_width, dur_width, stopped_width, now):
    """Print a single activity row in grouped format."""
    duration = format_duration(activity_duration_minutes(activity, now))
    dur_padded = pad_nbsp(duration, dur_width)
    start_padded = pad_nbsp(activity.start.strftime("%H:%M"), 7)
    stopped_padded = pad_nbsp(_get_stopped_str(activity), stopped_width)
    desc_padded = pad_nbsp(activity.description, desc_width)
    proj_padded = pad_nbsp(activity.project, proj_width)

    if activity.is_running():
        print(f"\033[32m{start_padded}\033[0m \033[32m{stopped_padded}\033[0m \033[32m{desc_padded}\033[0m \033[32m{proj_padded}\033[0m \033[32m{dur_padded}\033[0m ")
    elif is_multi_day(activity):
        print(f"\033[33m{start_padded}\033[0m \033[33m{stopped_padded}\033[0m \033[33m{desc_padded}\033[0m \033[33m{proj_padded}\033[0m \033[33m{dur_padded}\033[0m ")
    else:
        print(f"{start_padded} {stopped_padded} {desc_padded} {proj_padded} {dur_padded} ")

def _print_list_row_no_grouping(activity, desc_width, proj_width, dur_width, stopped_width, now):
    """Print a single activity row in no_grouping format."""
    duration = format_duration(activity_duration_minutes(activity, now))
    dur_padded = pad_nbsp(duration, dur_width)
    start_str = activity.start.strftime("%Y-%m-%d %H:%M")
    stopped_padded = pad_nbsp(_get_stopped_str(activity), stopped_width)
    desc_padded = pad_nbsp(activity.description, desc_width)
    proj_padded = pad_nbsp(activity.project, proj_width)

    if activity.is_running():
        print(f"\033[32m{start_str}\033[0m \033[32m{stopped_padded}\033[0m \033[32m{desc_padded}\033[0m \033[32m{proj_padded}\033[0m \033[32m{dur_padded}\033[0m ")
    elif is_multi_day(activity):
        print(f"\033[33m{start_str}\033[0m \033[33m{stopped_padded}\033[0m \033[33m{desc_padded}\033[0m \033[33m{proj_padded}\033[0m \033[33m{dur_padded}\033[0m ")
    else:
        print(f"{start_str} {stopped_padded} {desc_padded} {proj_padded} {dur_padded} ")

def print_list_grouped(activities, now):
    """Print list output grouped by date (with date group headers)."""
    desc_width, proj_width, dur_width, stopped_width = _get_list_widths(activities, now)
    _print_list_header_grouped(desc_width, proj_width, stopped_width)
    print()  # blank line before first group

    # Group by date
    date_groups = OrderedDict()
    for a in activities:
        d = a.start.date()
        if d not in date_groups:
            date_groups[d] = []
        date_groups[d].append(a)

    sorted_groups = sorted(date_groups.items())
    for group_idx, (d, day_activities) in enumerate(sorted_groups):
        total_minutes = sum(activity_duration_minutes(a, now) for a in day_activities)
        print(f"\033[1m{d.strftime('%Y-%m-%d')}\t{format_duration(total_minutes)}\033[0m")

        for a in day_activities:
            _print_list_row_grouped(a, desc_width, proj_width, dur_width, stopped_width, now)

        # Blank line between groups (but NOT after the last group)
        if group_idx < len(sorted_groups) - 1:
            print()

def print_list_flat(activities, now):
    """Print list output as flat list (no date group headers, grouped time format)."""
    desc_width, proj_width, dur_width, stopped_width = _get_list_widths(activities, now)
    _print_list_header_grouped(desc_width, proj_width, stopped_width)

    for a in activities:
        _print_list_row_grouped(a, desc_width, proj_width, dur_width, stopped_width, now)

def print_list_no_grouping(activities, now):
    """Print list output without grouping (full date+time format)."""
    desc_width, proj_width, dur_width, stopped_width = _get_list_widths(activities, now)
    _print_list_header_no_grouping(desc_width, proj_width, stopped_width)

    for a in activities:
        _print_list_row_no_grouping(a, desc_width, proj_width, dur_width, stopped_width, now)

def print_report(activities, now):
    """Print report output."""
    if not activities:
        return

    # Group by project -> description -> sum minutes
    project_map = {}
    for a in activities:
        if a.project not in project_map:
            project_map[a.project] = {}
        minutes = activity_duration_minutes(a, now)
        project_map[a.project][a.description] = project_map[a.project].get(a.description, 0) + minutes

    total_minutes = sum(sum(tasks.values()) for tasks in project_map.values())

    # Find max label width
    max_label_width = len("Total")
    for proj, tasks in project_map.items():
        max_label_width = max(max_label_width, len(proj))
        for task in tasks:
            max_label_width = max(max_label_width, 4 + len(task))

    # Find max duration width
    all_durations = []
    for proj, tasks in project_map.items():
        proj_total = sum(tasks.values())
        all_durations.append(format_duration(proj_total))
        for minutes in tasks.values():
            all_durations.append(format_duration(minutes))
    all_durations.append(format_duration(total_minutes))
    max_dur_width = max(len(d) for d in all_durations)

    for proj in sorted(project_map.keys()):
        tasks = project_map[proj]
        proj_total = sum(tasks.values())
        proj_dur = format_duration(proj_total)
        dots = max_label_width - len(proj)
        print(f"\033[1m{proj}{'.' * dots} {rjust(proj_dur, max_dur_width)}\033[0m")

        for task in sorted(tasks.keys()):
            minutes = tasks[task]
            task_dur = format_duration(minutes)
            indent_task = "    " + task
            dots = max_label_width - len(indent_task)
            print(f"{indent_task}{'.' * dots} {rjust(task_dur, max_dur_width)}")
        print()

    total_dur = format_duration(total_minutes)
    dots = max_label_width - len("Total")
    print(f"\033[1mTotal{'.' * dots} {rjust(total_dur, max_dur_width)}\033[0m")

def print_status(project_filter, running, today_minutes, week_minutes, month_minutes, now):
    """Print status output."""
    # Header
    sys.stdout.write("\033[2m\n =======\033[0m")
    if project_filter:
        sys.stdout.write(f"\033[3m Status for project: \033[0m\033[1m{project_filter}\033[0m\033[2m ======= \n")
    else:
        sys.stdout.write("\033[3m Status for \033[0m\033[1mALL\033[0m\033[3m projects \033[0m\033[2m ======= \n")

    # NOW line
    if not running:
        sys.stdout.write("\033[0m\033[2;3m\n  NOW: \033[0m\033[1m NO Activity\n\n")
    else:
        a = running[0]
        duration = format_duration(activity_duration_minutes(a, now))
        sys.stdout.write(f"\033[0m\033[2;3m\n  NOW: \033[0m\033[1;32m{a.description}\033[0m\033[2;3m on \033[0m\033[3m{a.project}\033[0m\033[2m ...... \033[0m\033[1m{duration}\033[0m\033[2m\n\n")

    # Timing rows
    today_dur = format_duration(today_minutes)
    week_dur = format_duration(week_minutes)
    month_dur = format_duration(month_minutes)

    sys.stdout.write(f"\033[0m\033[3m \033[0m\033[2;3m Today......................... \033[0m\033[1m{today_dur}\033[0m\033[3m\n")
    sys.stdout.write(f"\033[0m\033[3m \033[0m\033[2;3m Current week.................. \033[0m\033[1m{week_dur}\033[0m\033[3m\n")
    sys.stdout.write(f"\033[0m\033[3m \033[0m\033[2;3m Current month................. \033[0m\033[1m{month_dur}\033[0m\033[3m\n")
    sys.stdout.write("\033[0m\n")

