def build_date_filter(args):
    """Build from/to date filter from arguments."""
    today = date.today()

    if getattr(args, 'today', False):
        return today, today
    if getattr(args, 'yesterday', False):
        yesterday = today - timedelta(days=1)
        return yesterday, yesterday
    if getattr(args, 'current_week', False):
        weekday = today.weekday()  # 0=Monday
        monday = today - timedelta(days=weekday)
        sunday = monday + timedelta(days=6)
        return monday, sunday
    if getattr(args, 'last_week', False):
        weekday = today.weekday()
        this_monday = today - timedelta(days=weekday)
        last_monday = this_monday - timedelta(days=7)
        last_sunday = last_monday + timedelta(days=6)
        return last_monday, last_sunday

    from_date = None
    to_date = None

    if getattr(args, 'date', None):
        try:
            d = datetime.strptime(args.date, "%Y-%m-%d").date()
            return d, d
        except ValueError:
            pass

    if getattr(args, 'from_date', None):
        try:
            from_date = datetime.strptime(args.from_date, "%Y-%m-%d").date()
        except ValueError:
            pass

    if getattr(args, 'to_date', None):
        try:
            to_date = datetime.strptime(args.to_date, "%Y-%m-%d").date()
        except ValueError:
            pass

    return from_date, to_date

def parse_round(round_str):
    """Parse round string like '15m' or '4h' to minutes."""
    if round_str is None:
        return None
    if round_str.endswith('m'):
        try:
            return int(round_str[:-1])
        except ValueError:
            return None
    elif round_str.endswith('h'):
        try:
            return int(round_str[:-1]) * 60
        except ValueError:
            return None
    return None

def cmd_list(file_path, args):
    now = now_dt()
    from_date, to_date = build_date_filter(args)
    no_grouping = getattr(args, 'no_grouping', False)
    number = getattr(args, 'number', None)
    round_minutes = parse_round(getattr(args, 'round', None))
    project = getattr(args, 'project', None)

    # Determine if this is a single-day filter
    is_single_day = (from_date is not None and from_date == to_date)

    try:
        activities, _ = read_activities(file_path)

        if project:
            activities = [a for a in activities if a.project == project]

        activities = apply_date_filter(activities, from_date, to_date)

        if number is not None:
            if len(activities) > number:
                activities = activities[len(activities)-number:]

        if round_minutes:
            for a in activities:
                a.start = round_datetime(a.start, round_minutes)
                if a.end:
                    a.end = round_datetime(a.end, round_minutes)

        if not activities and (from_date is not None or to_date is not None or number is not None):
            # Check if we should show "No activity to display"
            # This happens when a filter is active and no activities match
            print("No activity to display")
            return

        print()
        if no_grouping:
            print_list_no_grouping(activities, now)
        elif is_single_day:
            print_list_flat(activities, now)
        else:
            print_list_grouped(activities, now)
        print()
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

def cmd_report(file_path, args):
    now = now_dt()
