    if not indexed_activities:
        return

    max_idx = max(i for i, _ in indexed_activities)
    idx_width = len(f"[{max_idx}]")

    desc_width = max((len(a.description) for _, a in indexed_activities), default=11)
    desc_width = max(desc_width, 11)  # "Description" = 11

    proj_width = max((len(a.project) for _, a in indexed_activities), default=7)
    proj_width = max(proj_width, 7)  # "Project" = 7

    # Header
    hash_col = pad_nbsp(" #", idx_width)
    desc_col = pad_nbsp("Description", desc_width)
    proj_col = pad_nbsp("Project", proj_width)
    print(f"\033[4m{hash_col}\033[0m \033[4m{desc_col}\033[0m \033[4m{proj_col}\033[0m ")

    # Display in REVERSE order (highest index = oldest, displayed first)
    for idx, activity in reversed(indexed_activities):
