def _get_list_widths(activities, now):
    """Get column widths for list output."""
    desc_width = max((len(a.description) for a in activities), default=11) if activities else 11
    desc_width = max(desc_width, 11)
    proj_width = max((len(a.project) for a in activities), default=7) if activities else 7
    proj_width = max(proj_width, 7)
    dur_width = max((len(format_duration(activity_duration_minutes(a, now))) for a in activities), default=8) if activities else 8
    dur_width = max(dur_width, 8)
    has_multiday = any(is_multi_day(a) for a in activities)
    stopped_width = 16 if has_multiday else 7
    return desc_width, proj_width, dur_width, stopped_width

def _print_list_header_grouped(desc_width, proj_width, stopped_width):
