def _get_stopped_str(activity):
    """Get stopped time string for an activity."""
    if activity.end is None:
        return "-"
    elif activity.end.date() != activity.start.date():
        return activity.end.strftime("%Y-%m-%d %H:%M")
    else:
        return activity.end.strftime("%H:%M")

def _print_list_row_grouped(activity, desc_width, proj_width, dur_width, stopped_width, now):
    """Print a single activity row in grouped format."""
    duration = format_duration(activity_duration_minutes(activity, now))
    dur_padded = pad_nbsp(duration, dur_width)
    start_padded = pad_nbsp(activity.start.strftime("%H:%M"), 7)
    stopped_padded = pad_nbsp(_get_stopped_str(activity), stopped_width)
    desc_padded = pad_nbsp(activity.description, desc_width)
    proj_padded = pad_nbsp(activity.project, proj_width)

    if activity.is_running():
        print(f"\033[32m{start_padded}\033[0m \033[32m{stopped_padded}\033[0m \033[32m{desc_padded}\033[0m \033[32m{proj_padded}\033[0m \033[32m{dur_padded}\033[0m ")
    elif is_multi_day(activity):
        print(f"\033[33m{start_padded}\033[0m \033[33m{stopped_padded}\033[0m \033[33m{desc_padded}\033[0m \033[33m{proj_padded}\033[0m \033[33m{dur_padded}\033[0m ")
    else:
        print(f"{start_padded} {stopped_padded} {desc_padded} {proj_padded} {dur_padded} ")

def _print_list_row_no_grouping(activity, desc_width, proj_width, dur_width, stopped_width, now):
    """Print a single activity row in no_grouping format."""
    duration = format_duration(activity_duration_minutes(activity, now))
    dur_padded = pad_nbsp(duration, dur_width)
    start_str = activity.start.strftime("%Y-%m-%d %H:%M")
    stopped_padded = pad_nbsp(_get_stopped_str(activity), stopped_width)
    desc_padded = pad_nbsp(activity.description, desc_width)
    proj_padded = pad_nbsp(activity.project, proj_width)

    if activity.is_running():
        print(f"\033[32m{start_str}\033[0m \033[32m{stopped_padded}\033[0m \033[32m{desc_padded}\033[0m \033[32m{proj_padded}\033[0m \033[32m{dur_padded}\033[0m ")
    elif is_multi_day(activity):
        print(f"\033[33m{start_str}\033[0m \033[33m{stopped_padded}\033[0m \033[33m{desc_padded}\033[0m \033[33m{proj_padded}\033[0m \033[33m{dur_padded}\033[0m ")
