def print_started(activity):
    print(f'Started activity: "{activity.description}" ({activity.project}) at {activity.start.strftime("%Y-%m-%d %H:%M")}')

def print_stopped(activity):
    print(f'Stopped activity: "{activity.description}" ({activity.project}) started at {activity.start.strftime("%Y-%m-%d %H:%M")} ({format_duration(activity.duration_minutes())})')

def print_canceled(activity):
    print(f'Canceled activity: "{activity.description}" ({activity.project}) started at {activity.start.strftime("%Y-%m-%d %H:%M")}')

def print_changed(activity):
    print(f'Changed activity: "{activity.description}" ({activity.project}) started at {activity.start.strftime("%Y-%m-%d %H:%M")}')

# ============================================================
# Duration calculations
# ============================================================

def calc_duration_by_start_date(activities, start_date, now):
    """Sum durations of all activities that started on start_date."""
    return sum(activity_duration_minutes(a, now) for a in activities if a.start.date() == start_date)

def calc_duration_by_start_week(activities, monday, now):
    """Sum durations of all activities that started in the week starting on monday."""
    sunday = monday + timedelta(days=6)
    return sum(activity_duration_minutes(a, now) for a in activities if monday <= a.start.date() <= sunday)

def calc_duration_by_start_month(activities, year, month, now):
    """Sum durations of all activities that started in the given year/month."""
    return sum(activity_duration_minutes(a, now) for a in activities if a.start.year == year and a.start.month == month)

