def cmd_status(file_path, project_filter):
    now = now_dt()
    today = date.today()
    try:
        activities, errors = read_activities(file_path)
        print_warnings(errors)
        if project_filter:
            filtered = [a for a in activities if a.project == project_filter]
        else:
            filtered = activities
        running = [a for a in filtered if a.is_running()]
        monday = today - timedelta(days=today.weekday())
        today_minutes = calc_duration_by_start_date(filtered, today, now)
        week_minutes = calc_duration_by_start_week(filtered, monday, now)
        month_minutes = calc_duration_by_start_month(filtered, today.year, today.month, now)
        print_status(project_filter, running, today_minutes, week_minutes, month_minutes, now)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

