def cmd_check(file_path):
    try:
        with open(file_path, 'r') as f:
            content = f.read()
    except FileNotFoundError:
        print(f"Error: Could not read from file: {file_path}\n\nCaused by:\n    No such file or directory (os error 2)", file=sys.stderr)
        sys.exit(1)
    except IOError as e:
        print(f"Error: Could not read from file: {file_path}\n\nCaused by:\n    {e}", file=sys.stderr)
        sys.exit(1)
    errors = []
    for i, line in enumerate(content.split('\n')):
        line_num = i + 1
        if not line.strip():
            continue
        _, err = parse_activity(line, line_num)
        if err:
            errors.append((line_num, line, err))
    if not errors:
        print("All lines in the file have been successfully parsed as activities.")
    else:
        print(f"Found {len(errors)} line(s) with parsing errors")
        print()
        for _, line, err in errors:
            print(line)
            print(f"  -> {err}")

def cmd_sanity(file_path):
    try:
        activities, _ = read_activities(file_path)
        found_issues = False
        for i in range(1, len(activities)):
            prev, curr = activities[i-1], activities[i]
            if prev.end and curr.start < prev.end:
                line_num = curr.line_number or (i + 1)
                end_str = curr.end.strftime("%Y-%m-%d %H:%M") if curr.end else ""
                print("Activity started before another activity ended")
                print(f"{curr.description} (Started: {curr.start.strftime('%Y-%m-%d %H:%M')}, Ended: {end_str}, Line: {line_num})")
                print()
                found_issues = True
        if not found_issues:
            print("No unusual activities.")
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

def cmd_continue(file_path, number, description, project, time_str):
    now = with_time_override(time_str)
    try:
        activities, errors = read_activities(file_path)
        print_warnings(errors)
        for a in activities:
            if a.is_running():
                a.end = now
                print_stopped(a)
        unique = get_unique_recent_activities(activities)
        found = next((a for idx, a in unique if idx == number), None)
        if found:
            desc = description or found.description
            proj = project or found.project
            new_activity = Activity(proj, desc, now)
            activities.append(new_activity)
            write_activities(file_path, activities)
            print_started(new_activity)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

def cmd_edit(file_path, editor):
    if not editor:
        print("Error: No editor specified. Use -e option or set EDITOR environment variable.", file=sys.stderr)
        sys.exit(1)
    os.execlp(editor, editor, file_path)

