def parse_args():
    args = sys.argv[1:]

    # Global flags
    file_path = os.environ.get('BARTIB_FILE')

    i = 0
    while i < len(args):
        if args[i] in ('-h', '--help'):
            print_main_help()
            sys.exit(0)
        elif args[i] in ('-V', '--version'):
            print(f"bartib 1.1.0")
            sys.exit(0)
        elif args[i] == '-f':
            i += 1
            if i >= len(args):
                error_exit("argument -f requires a value")
            file_path = args[i]
        elif args[i].startswith('-f') and len(args[i]) > 2:
            file_path = args[i][2:]
        elif not args[i].startswith('-'):
            break
        else:
            break
        i += 1

    if i >= len(args):
        print_main_help()
        sys.exit(0)

    subcommand = args[i]
    sub_args = args[i+1:]

    return file_path, subcommand, sub_args

