def get_date_filter(args):
    today = date.today()
    if args.get('today'):
        return today, today
    if args.get('yesterday'):
        y = today - timedelta(days=1)
        return y, y
    if args.get('current_week'):
        monday = today - timedelta(days=today.weekday())
        return monday, monday + timedelta(days=6)
    if args.get('last_week'):
        this_monday = today - timedelta(days=today.weekday())
        last_monday = this_monday - timedelta(days=7)
        return last_monday, last_monday + timedelta(days=6)
    if args.get('date'):
        try:
            d = datetime.strptime(args['date'], "%Y-%m-%d").date()
            return d, d
        except ValueError:
            pass
    from_date = None
    to_date = None
    if args.get('from_date'):
        try:
            from_date = datetime.strptime(args['from_date'], "%Y-%m-%d").date()
        except ValueError:
            pass
    if args.get('to_date'):
        try:
            to_date = datetime.strptime(args['to_date'], "%Y-%m-%d").date()
        except ValueError:
            pass
    return from_date, to_date

def parse_round_str(s):
    if not s:
        return None
    if s.endswith('m'):
        try:
            return int(s[:-1])
        except ValueError:
            return None
    elif s.endswith('h'):
        try:
            return int(s[:-1]) * 60
        except ValueError:
            return None
    return None

def cmd_list(file_path, args):
    now = now_dt()
    from_date, to_date = get_date_filter(args)
    no_grouping = args.get('no_grouping', False)
    number = args.get('number')
    round_minutes = parse_round_str(args.get('round'))
    project = args.get('project')
    is_single_day = (from_date is not None and from_date == to_date)
    try:
        activities, errors = read_activities(file_path)
        print_warnings(errors)
        if project:
            activities = [a for a in activities if a.project == project]
        activities = apply_date_filter(activities, from_date, to_date)
        if number is not None:
            if len(activities) > number:
                activities = activities[len(activities)-number:]
        if round_minutes:
            for a in activities:
                a.start = round_datetime(a.start, round_minutes)
                if a.end:
                    a.end = round_datetime(a.end, round_minutes)
        if not activities:
            print("No activity to display")
            return
        print()
        if no_grouping:
            print_list_no_grouping(activities, now)
        elif is_single_day:
            print_list_flat(activities, now)
        else:
            print_list_grouped(activities, now)
        print()
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

def cmd_report(file_path, args):
    now = now_dt()
    from_date, to_date = get_date_filter(args)
    round_minutes = parse_round_str(args.get('round'))
    project = args.get('project')
    try:
