    'search': """{prog}-search \nsearch for existing descriptions and projects\n\nUSAGE:\n    {prog} search <SEARCH_TERM>\n\nFLAGS:\n    -h, --help    Prints help information\n\nARGS:\n    <SEARCH_TERM>    the search term [default: '']""",
