}

def print_main_help():
    print(MAIN_HELP.format(prog=PROG))

def print_subcommand_help(subcmd):
    if subcmd in SUBCOMMAND_HELP:
        print(SUBCOMMAND_HELP[subcmd].format(prog=PROG))
    else:
        print(MAIN_HELP.format(prog=PROG))

def error_exit(msg, usage=''):
    print(f"error: {msg}", file=sys.stderr)
    if usage:
        print(f"\nUSAGE:\n    {usage}", file=sys.stderr)
        print("\nFor more information try --help", file=sys.stderr)
    sys.exit(1)

# ============================================================
# Argument parsing (manual, matching clap 2.x behavior)
# ============================================================

def parse_args():
    args = sys.argv[1:]

    # Global flags
    file_path = os.environ.get('BARTIB_FILE')

    i = 0
    while i < len(args):
        if args[i] in ('-h', '--help'):
            print_main_help()
            sys.exit(0)
        elif args[i] in ('-V', '--version'):
            print(f"bartib 1.1.0")
            sys.exit(0)
        elif args[i] == '-f':
            i += 1
            if i >= len(args):
                error_exit("argument -f requires a value")
            file_path = args[i]
        elif args[i].startswith('-f') and len(args[i]) > 2:
            file_path = args[i][2:]
        elif not args[i].startswith('-'):
            break
        else:
            break
        i += 1

    if i >= len(args):
        print_main_help()
        sys.exit(0)

    subcommand = args[i]
    sub_args = args[i+1:]

    return file_path, subcommand, sub_args

def check_help(sub_args, subcmd):
    """Check if -h/--help is in sub_args, print subcommand help if so."""
    if '-h' in sub_args or '--help' in sub_args:
        print_subcommand_help(subcmd)
        sys.exit(0)

def get_opt(sub_args, *flags, default=None, takes_value=True):
    """Get option value from args."""
    for i, arg in enumerate(sub_args):
        if arg in flags:
            if takes_value:
                if i + 1 < len(sub_args):
                    return sub_args[i + 1]
                else:
                    return default
            else:
                return True
    return default

def has_flag(sub_args, *flags):
    return any(f in sub_args for f in flags)

def get_positional(sub_args, index=0):
    """Get positional arg (non-flag)."""
    pos = [a for a in sub_args if not a.startswith('-')]
    if index < len(pos):
        return pos[index]
    return None

def parse_subcommand_start(sub_args):
    check_help(sub_args, 'start')
    description = get_opt(sub_args, '-d', '--description')
    project = get_opt(sub_args, '-p', '--project')
    time_str = get_opt(sub_args, '-t', '--time')
    if description is None:
        error_exit(
            "The following required arguments were not provided:\n    --description <DESCRIPTION>",
            f"{PROG} start [OPTIONS] --description <DESCRIPTION> --project <PROJECT>"
        )
    if project is None:
        error_exit(
            "The following required arguments were not provided:\n    --project <PROJECT>",
            f"{PROG} start [OPTIONS] --description <DESCRIPTION> --project <PROJECT>"
        )
    return description, project, time_str

def parse_subcommand_list(sub_args):
    check_help(sub_args, 'list')
    return {
        'today': has_flag(sub_args, '--today'),
        'yesterday': has_flag(sub_args, '--yesterday'),
        'current_week': has_flag(sub_args, '--current_week'),
        'last_week': has_flag(sub_args, '--last_week'),
        'no_grouping': has_flag(sub_args, '--no_grouping'),
        'date': get_opt(sub_args, '-d', '--date'),
        'from_date': get_opt(sub_args, '--from'),
        'to_date': get_opt(sub_args, '--to'),
        'number': int(get_opt(sub_args, '-n', '--number')) if get_opt(sub_args, '-n', '--number') else None,
        'project': get_opt(sub_args, '-p', '--project'),
        'round': get_opt(sub_args, '--round'),
    }

def parse_subcommand_report(sub_args):
    check_help(sub_args, 'report')
    return {
        'today': has_flag(sub_args, '--today'),
        'yesterday': has_flag(sub_args, '--yesterday'),
        'current_week': has_flag(sub_args, '--current_week'),
        'last_week': has_flag(sub_args, '--last_week'),
        'date': get_opt(sub_args, '-d', '--date'),
        'from_date': get_opt(sub_args, '--from'),
        'to_date': get_opt(sub_args, '--to'),
        'project': get_opt(sub_args, '-p', '--project'),
        'round': get_opt(sub_args, '--round'),
    }

def main():
    file_path, subcommand, sub_args = parse_args()

    def require_file():
        if file_path is None:
            print("Error: Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable", file=sys.stderr)
            sys.exit(1)
        return file_path

    if subcommand == 'help':
        if sub_args:
            print_subcommand_help(sub_args[0])
        else:
            print_main_help()
        sys.exit(0)
    elif subcommand == 'cancel':
        check_help(sub_args, 'cancel')
        fp = require_file()
        cmd_cancel(fp)
    elif subcommand == 'change':
        check_help(sub_args, 'change')
        fp = require_file()
        description = get_opt(sub_args, '-d', '--description')
        project = get_opt(sub_args, '-p', '--project')
        time_str = get_opt(sub_args, '-t', '--time')
        cmd_change(fp, description, project, time_str)
    elif subcommand == 'check':
        check_help(sub_args, 'check')
        fp = require_file()
        cmd_check(fp)
    elif subcommand == 'continue':
        check_help(sub_args, 'continue')
        fp = require_file()
        number_str = get_positional(sub_args)
        number = int(number_str) if number_str and number_str.isdigit() else 0
        description = get_opt(sub_args, '-d', '--description')
        project = get_opt(sub_args, '-p', '--project')
        time_str = get_opt(sub_args, '-t', '--time')
        cmd_continue(fp, number, description, project, time_str)
    elif subcommand == 'current':
        check_help(sub_args, 'current')
        fp = require_file()
        cmd_current(fp)
    elif subcommand == 'edit':
        check_help(sub_args, 'edit')
        fp = require_file()
        editor = get_opt(sub_args, '-e') or os.environ.get('EDITOR')
        cmd_edit(fp, editor)
    elif subcommand == 'last':
        check_help(sub_args, 'last')
        fp = require_file()
        number_str = get_opt(sub_args, '-n', '--number')
        number = int(number_str) if number_str else 10
        cmd_last(fp, number)
    elif subcommand == 'list':
        fp = require_file()
        list_args = parse_subcommand_list(sub_args)
        cmd_list(fp, list_args)
    elif subcommand == 'projects':
        check_help(sub_args, 'projects')
        fp = require_file()
        current_only = has_flag(sub_args, '-c', '--current')
        no_quotes = has_flag(sub_args, '-n', '--no-quotes')
        cmd_projects(fp, current_only, no_quotes)
    elif subcommand == 'report':
        fp = require_file()
        report_args = parse_subcommand_report(sub_args)
        cmd_report(fp, report_args)
    elif subcommand == 'sanity':
        check_help(sub_args, 'sanity')
        fp = require_file()
        cmd_sanity(fp)
    elif subcommand == 'search':
        check_help(sub_args, 'search')
        fp = require_file()
        term = get_positional(sub_args) or ''
        cmd_search(fp, term)
    elif subcommand == 'start':
        fp = require_file()
        description, project, time_str = parse_subcommand_start(sub_args)
        cmd_start(fp, description, project, time_str)
    elif subcommand == 'status':
        check_help(sub_args, 'status')
        fp = require_file()
        project = get_opt(sub_args, '-p', '--project')
        cmd_status(fp, project)
    elif subcommand == 'stop':
        check_help(sub_args, 'stop')
        fp = require_file()
        time_str = get_opt(sub_args, '-t', '--time')
        cmd_stop(fp, time_str)
    else:
        # Unknown subcommand
        print(f"error: Found argument '{subcommand}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {PROG} [OPTIONS] <SUBCOMMAND>\n\nFor more information try --help", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()
