    _print_list_header_grouped(desc_width, proj_width, stopped_width)
    for a in activities:
        _print_list_row_grouped(a, desc_width, proj_width, dur_width, stopped_width, now)

def print_list_no_grouping(activities, now):
    desc_width, proj_width, dur_width, stopped_width = _get_list_widths(activities, now)
    _print_list_header_no_grouping(desc_width, proj_width, stopped_width)
    for a in activities:
        _print_list_row_no_grouping(a, desc_width, proj_width, dur_width, stopped_width, now)

def print_report(activities, now):
    if not activities:
        print(f"\033[1mTotal {format_duration(0)}\033[0m")
        return
    project_map = {}
    for a in activities:
        if a.project not in project_map:
            project_map[a.project] = {}
        minutes = activity_duration_minutes(a, now)
        project_map[a.project][a.description] = project_map[a.project].get(a.description, 0) + minutes
    total_minutes = sum(sum(t.values()) for t in project_map.values())
    max_label_width = max(
        len("Total"),
        max((len(p) for p in project_map), default=0),
        max((4 + len(t) for tasks in project_map.values() for t in tasks), default=0)
    )
    all_dur_strs = [format_duration(sum(t.values())) for t in project_map.values()]
    all_dur_strs += [format_duration(m) for t in project_map.values() for m in t.values()]
    all_dur_strs.append(format_duration(total_minutes))
    max_dur_width = max(len(d) for d in all_dur_strs)
    for proj in sorted(project_map.keys()):
        tasks = project_map[proj]
        proj_total = sum(tasks.values())
        dots = max_label_width - len(proj)
        print(f"\033[1m{proj}{'.' * dots} {rjust(format_duration(proj_total), max_dur_width)}\033[0m")
        for task in sorted(tasks.keys()):
            indent_task = "    " + task
            dots = max_label_width - len(indent_task)
            print(f"{indent_task}{'.' * dots} {rjust(format_duration(tasks[task]), max_dur_width)}")
        print()
    dots = max_label_width - len("Total")
    print(f"\033[1mTotal{'.' * dots} {rjust(format_duration(total_minutes), max_dur_width)}\033[0m")

def print_status(project_filter, running, today_minutes, week_minutes, month_minutes, now):
    sys.stdout.write("\033[2m\n =======\033[0m")
    if project_filter:
        sys.stdout.write(f"\033[3m Status for project: \033[0m\033[1m{project_filter}\033[0m\033[2m ======= \n")
    else:
        sys.stdout.write("\033[3m Status for \033[0m\033[1mALL\033[0m\033[3m projects \033[0m\033[2m ======= \n")
    if not running:
        sys.stdout.write("\033[0m\033[2;3m\n  NOW: \033[0m\033[1m NO Activity\n\n")
    else:
        a = running[0]
        duration = format_duration(activity_duration_minutes(a, now))
        if project_filter:
            sys.stdout.write(f"\033[0m\033[2;3m\n  NOW: \033[0m\033[1;32m{a.description}\033[0m\033[2m ...... \033[0m\033[1m{duration}\033[0m\033[2m\n\n")
        else:
            sys.stdout.write(f"\033[0m\033[2;3m\n  NOW: \033[0m\033[1;32m{a.description}\033[0m\033[2;3m on \033[0m\033[3m{a.project}\033[0m\033[2m ...... \033[0m\033[1m{duration}\033[0m\033[2m\n\n")
    today_dur = format_duration(today_minutes)
    week_dur = format_duration(week_minutes)
    month_dur = format_duration(month_minutes)
    sys.stdout.write(f"\033[0m\033[3m \033[0m\033[2;3m Today......................... \033[0m\033[1m{today_dur}\033[0m\033[3m\n")
    sys.stdout.write(f"\033[0m\033[3m \033[0m\033[2;3m Current week.................. \033[0m\033[1m{week_dur}\033[0m\033[3m\n")
    sys.stdout.write(f"\033[0m\033[3m \033[0m\033[2;3m Current month................. \033[0m\033[1m{month_dur}\033[0m\033[3m\n")
    sys.stdout.write("\033[0m\n")

